quests[13330] = { id = 13330, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood of the Chosen", description = "Those vrykul that have gained the favor of the Lich King call themselves the Ymirjar. They inhabit a city in the center of Icecrown. We have a lot of preparations to make before we assault Icecrown Citadel, and the one that stands before us now is routing these so-called \"Chosen\" of the Lich King.\n\nGo to their city, Ymirheim, and slaughter them in their home. Let there be no questions as to who the stronger combatants are here.", sourceObjective = "Warbringer Davos Rioht on Orgrim's Hammer has sent you to kill 20 vrykul in Ymirheim.", completion = "Not so strong after all, it seems. The Lich King will get what's coming to him.", sourceObjectiveStatus = "unverified-source-field" }
quests[13331] = { id = 13331, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keeping the Alliance Blind", description = "The Alliance is tenacious, I'll give them that, but it'll take more than that to stop us. Take this SGM-3 with you and shoot down the Skybreaker's recon fighters once again.\n\nI doubt the message will get through their thick skulls, but there are enough missiles to keep trying to get our point across. Go and find their fighters flying above the Valley of Fallen Heroes, west of Aldur'thar, and don't come back until you've made wreckage of them.", sourceObjective = "Use the SGM-3 to destroy 6 Skybreaker Recon Fighters, then report back to Sky-Reaver Korm Blackscar aboard Orgrim's Hammer.", progress = "Have you eliminated the Alliance's reconnaissance operations in the western part of the glacier?", completion = "Well done, once again. Horde superiority is assured, at least until those Alliance pukes decide to challenge us again.", sourceObjectiveStatus = "unverified-source-field" }
quests[13332] = { id = 13332, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raise the Barricades", description = "When our forces begin to move beyond Aldur'thar, they will be vulnerable to attack from the Ironwall Rampart and the broad glacier below.\n\nWe have neither the time nor the materials to build fortifications, but we can put up some barricades to shield our men from fire and break up Scourge charges.\n\nTake this barricade kit to the Valley of Fallen Heroes, on the west side of Aldur'thar. Locate the markers I've placed there and use this kit to construct your barricades there.", sourceObjective = "Thassarian, aboard the Skybreaker, wants you to construct 8 Barricades using your Barricade Construction Kit.", completion = "<Thassarian nods.>\n\nGood. It's not much protection, but it's better than nothing. That gate is still the perfect choke point if the Scourge commanders know what they're doing. We must gain control of as much of the surrounding area as possible.", sourceObjectiveStatus = "unverified-source-field" }
quests[13333] = { id = 13333, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Capture More Dispatches", description = "Despite our efforts, the Horde continues to send scouts to the area of the Icecrown Glacier, to the west of the Ironwall Rampart and Aldur'thar.\n\nWe can't afford to let the Horde gain the upper hand with this scouting operation. Take the dart gun with you again and show the Orgrim's Hammer scouts no mercy! Bring the captured dispatches to me.\n\nThe Horde's wasted efforts will be our gain.", sourceObjective = "Capture 6 Orgrim's Hammer Dispatches from Orgrim's Hammer Scouts and bring them to High Captain Justin Bartlett aboard the Skybreaker.", progress = "Have you intercepted those dispatches?", completion = "<The high captain accepts the dispatches.>\n\nThis is just what we need. Not even the Horde is so stupid as to charge in blindly against the Scourge. With their reports in hand, we'll be well prepared.", sourceObjectiveStatus = "unverified-source-field" }
quests[13334] = { id = 13334, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodspattered Banners", description = "In the Valley of Fallen Heroes and Icecrown Glacier, to the west of Aldur'thar, the Scourge seeks to use the fallen against us. Scourge lieutenants have woken the valley's dead and imbued them with fearsome strength and fervor. The banners carried by the Scourge leaders in the glacier area are the source of these powers. Kill the banner-bearers, and you will weaken the converted heroes they lead.\n\nIt falls to you to rid us of this obstacle, and test the resistance before the main body can advance.", sourceObjective = "Thassarian, aboard the Skybreaker, wants you to kill 5 Scourge Banner-Bearers, 5 Scourge Converters, and 20 Converted Heroes.", progress = "Have you killed the banner-bearers and stopped their attempt to use the fallen against us?", completion = "You have removed the Scourge banner-bearers and their minions? Good. Our preparations must continue.", sourceObjectiveStatus = "unverified-source-field" }
quests[13335] = { id = 13335, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Before the Gate of Horror", description = "The Conflagration, the ground before Corp'rethar, south of the Ironwall Rampart, is where the Lich King's elite soldiers have formed up to defend the citadel.\n\nLed by a contingent of death knights, a legion of skeletal reavers bars the way. I fear that even when these reavers fall, the Scourge will simply reconstitute them and send them back at us.\n\nI've come up with a plan to stop this, but I have no way of knowing if it will work. Take this solution and use it to dissolve the remains of the reavers.", sourceObjective = "Thassarian, aboard the Skybreaker, wants you to use the Volatile Acid to dissolve the corpses of 6 Skeletal Reavers.", completion = "<Thassarian listens as you describe your successful tests.>\n\nSo the acid worked? Good. We'll need it when the army goes up against the reavers in force.", sourceObjectiveStatus = "unverified-source-field" }
quests[13336] = { id = 13336, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood of the Chosen", description = "Those vrykul that have gained the favor of the Lich King call themselves the Ymirjar. They inhabit a city in the center of Icecrown. We have a lot of preparations to make before we assault Icecrown Citadel, and the one that stands before us now is routing these so-called \"Chosen\" of the Lich King.\n\nGo to their city, Ymirheim, and slaughter them in their home. Let there be no questions as to who the stronger combatants are here.", sourceObjective = "Knight-Captain Drosche on the Skybreaker has sent you to kill 20 vrykul in Ymirheim.", completion = "The traitor king will fall. Of that I have no doubt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13337] = { id = 13337, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ironwall Rampart", description = "The Ironwall Rampart overlooks the Valley of Fallen Heroes, west of Aldur'thar. The rampart dominates the fields below on all sides. We will not be able to advance if the rampart cannot be taken, but it is held by Grimkor the Wicked and his Cult of the Damned disciples.\n\nIf you can weaken Grimkor, our forces will know what to expect as we advance. Take this rune of distortion. Unleashing its power near Grimkor's orb at the end of the rampart should be enough to get the necromancer's attention.", sourceObjective = "Defeat Grimkor the Wicked and return to Thassarian aboard the Skybreaker.", progress = "Have you completed your mission?", completion = "So Grimkor has fallen by your hand? Excellent work. With him out of the way, our chances of taking and holding the rampart during the assault are greatly improved.", sourceObjectiveStatus = "unverified-source-field" }
quests[13338] = { id = 13338, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Guardians of Corp'rethar", description = "Corp'rethar, called the Horror Gate. It is the last barrier between us and the Icecrown Citadel. It waits to the south of the Ironwall Rampart, beyond the glacier and the Conflagration. By the time our troops reach it, they will be exhausted and worse.\n\nWe must weaken its defenses, or our army's strength will break upon its walls.\n\nIts battlements are manned by some of the Lich King's fiercest and most zealous servants. Do all you can to destroy these guardians and hope it is enough.", sourceObjective = "Thassarian, aboard the Skybreaker, wants you to kill 5 Harbingers of Horror and 5 Corp'rethar Guardians.", completion = "I hope your success at Corp'rethar will prove an omen of the battle ahead. The Lich King cannot sit idly by as we march to the very gates of his stronghold.", sourceObjectiveStatus = "unverified-source-field" }
quests[13339] = { id = 13339, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shatter the Shards", description = "Atop the battlements of Corp'rethar, the Lich King's minions have erected three crystals, the shards of horror, despair, and suffering. Should our men reach the walls of Corp'rethar, he will unleash these weapons on our army.\n\nIn full effect, the crystals will afflict the minds of our men with paralyzing pain and fear. Then, the Scourge will be able to slaughter them at will.\n\nFind these shards, destroy them, and bring me their broken remains. We cannot allow the Lich King to deploy these weapons!", sourceObjective = "Bring the Broken Shard of Horror, the Broken Shard of Despair, and the Broken Shard of Suffering to Thassarian, aboard the Skybreaker.", progress = "Have you shattered the Lich King's new weapons?", completion = "<Thassarian takes the crystal shards from you and speaks in a quiet voice.>\n\nI remember these...\n\nLesser men would easily crumble beneath their assault. You have done well in removing their threat.", sourceObjectiveStatus = "unverified-source-field" }
quests[13340] = { id = 13340, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Joining the Assault", description = "We need more men to join the main assault on Ymirheim.\n\nAny warrior with half a brain can tell you that vrykul are fierce fighters and should not be taken lightly. That goes two-fold for the Ymirjar. They have shown us no restraint in proving why the Lich King deemed them worthy.\n\nGround Commander Xutjja is overseeing the assault. The city itself is located in the center of Icecrown - Xutjja's troops are positioned near the edge of the glacier, north of the city.", sourceObjective = "Report to Ground Commander Xutjja at the edge of the glacier north of Ymirheim.", completion = "More meat for the grinder. Welcome to hell, soldier.\n\nMy men are leading the assault on the gate from this position, and we're dropping some infiltrators in the city via air - we need more people on both fronts. I have a feeling that this attack will be going on for some time.", sourceObjectiveStatus = "unverified-source-field" }
quests[13341] = { id = 13341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Joining the Assault", description = "We need more men to join the main assault on Ymirheim.\n\nAny warrior with half a brain can tell you that vrykul are fierce fighters and should not be taken lightly. That goes two-fold for the Ymirjar. They have shown no restraint in proving to us why the Lich King deemed them worthy.\n\nGround Commander Koup is overseeing the assault. The city itself is located in the center of Icecrown - Koup's troops are positioned near the edge of the glacier, east of the city.", sourceObjective = "Report to Ground Commander Koup at the edge of the glacier east of Ymirheim.", completion = "Welcome to hell, soldier.\n\nMy men are leading the assault on the gate from this position, and we're dropping some infiltrators in the city via air - we need more people on both fronts. I have a feeling that this attack will be going on for some time.", sourceObjectiveStatus = "unverified-source-field" }
quests[13342] = { id = 13342, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not a Bug", description = "Alright, <friend/missy>, time to plant a bug.\n\nRelax, it's not a bug exactly, but it'll serve our purposes.\n\nIn the northern portion of Aldur'thar the cult's void summoners enslave demonic minions. Use this rod to siphon the dark matter from the corpses of these enslaved minions, and then use their summoning crystal to bring our little spy into being.\n\nUntil it is discovered, the messenger will serve as our eyes and ears, discreetly observing the actions of our enemy.", sourceObjective = "Thassarian, aboard the Skybreaker, wants you to collect 5 Dark Matters and summon a Dark Messenger at Aldur'thar.", completion = "You have done well, {class}.\n\nThe messenger has already turned up some valuable information.", sourceObjectiveStatus = "unverified-source-field" }
quests[13343] = { id = 13343, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mystery of the Infinite, Redux", description = "There you are! Or, were we just talking?\n\n<Chromie muses over the temporal possibilities.>\n\nAnyway, the Infinites are after you! Well, not you per-se. Rather, they're after the past version of you that defended the Hourglass of Eternity. You remember, right?\n\nThat was you back then, except it's you now too. Wait, that's not important. What is important is that you head back to the Bronze Dragonshrine and defend yourself and the hourglass from their attacks before you get erased from history!", sourceObjective = "Chromie, at the top of Wyrmrest Temple, has asked you to travel once more to the Bronze Dragonshrine.\n\nOnce inside, place the Hourglass of Eternity on the ground and help your Past Self to protect it from the forces of the Infinite Dragonflight.", completion = "Oh my goodness, you made it! I was uncertain.\n\nYou flickered in and out of the time stream there for a moment during the fight! I thought for sure that we'd lost you!\n\nBut here you are safe and sound, with your past self rescued, on the other side of the time loop you were in.\n\nYou're quite the temporal hero, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[13344] = { id = 13344, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not a Bug", description = "The cultists have discovered the last messenger you summoned, {race}.\n\nWhile it was quite informative, it's important that we continue to monitor their every move.\n\nUse this rod to siphon the dark matter from the corpses of enslaved minions at Aldur'thar. Then use their summoning crystal to bring another dark messenger into being.\n\nUntil it is discovered, the messenger will serve as our eyes and ears, discreetly observing the actions of our enemy.", sourceObjective = "Thassarian, aboard the Skybreaker, wants you to collect 5 Dark Matters and summon a Dark Messenger at Aldur'thar.", completion = "Well done, friend.\n\nThe messenger is up and reporting in as we speak.", sourceObjectiveStatus = "unverified-source-field" }
quests[13345] = { id = 13345, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Need More Info", description = "The Cult of the Damned are notorious for concocting grandiose plans that in the end, rarely succeed. But something feels different this time....\n\nPerhaps it's the proximity to the Lich King that has their fervor heightened. Whatever it is, they appear to be more confident than ever. We must know what feeds this bravado and then find a way to strip them of it!\n\nI believe the key lies with their researchers. Find out what they're up to and report back to me with the details.", sourceObjective = "Thassarian, aboard the Skybreaker, wants you to collect the 3 pages of Cultists' Research from the Cult Researchers at Aldur'thar and use them to create the Cult of the Damned Thesis.", progress = "Have you determined what their researchers are up to, {race}?", completion = "This is alarming, indeed....", sourceObjectiveStatus = "unverified-source-field" }
quests[13346] = { id = 13346, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Rest For The Wicked", description = "These fools have actually stumbled upon something that could pose a serious threat to our plans!\n\nThe leader of this particular sect, Alumeth, has ritualistically sacrificed himself and now his underlings are channeling power to his soul.\n\nIf he's allowed to rest, their efforts will soon transform him into a mighty adversary.\n\nCombine his heart, skull, scepter and robes from around their chamber and use his remains on the crystal there.\n\nHurry, {race}! Destroy him before he becomes any more powerful!", sourceObjective = "Thassarian, aboard the Skybreaker, wants you to defeat Alumeth the Ascended at Aldur'thar.", progress = "Well, friend? Were you successful against Alumeth?", completion = "Alumeth has suffered a sound defeat, but I sense that his spirit still lingers...", sourceObjectiveStatus = "unverified-source-field" }
quests[13347] = { id = 13347, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reborn From The Ashes", description = "Our fate is emblazoned upon our souls at birth. Bolvar's fall, while tragic, was unavoidable.\n\nAll that you can do now is honor your hero, {name}. Collect Bolvar's shield from the field of battle and return it to your king. When you present the shield to Varian, tell him this: \"All is not lost. From the ashes of the fallen will rise a force that will unite nations and purge the evil from this world.\"\n\nHe mustn't lose faith. Go now, {name}. Your people need a hero. They need you.", sourceObjective = "Gather Fordragon's Shield from the field of battle at Angrathar the Wrath Gate and return it to King Varian Wrynn at Stormwind Keep in Stormwind City.", progress = "<King Wrynn brushes away a tear.>\n\n<King Wrynn nods.>\n\nThis is my fault.", completion = "The Dragon Queen is right, {name}. All is not lost. I will be the force that rises from the ashes and I will purge the evil of the Horde from this world. The deaths of our brothers and sisters will not have been in vain.", sourceObjectiveStatus = "unverified-source-field" }
quests[13348] = { id = 13348, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Futility", description = "Do you see now?  Sending your men against the prince's armies just swells their numbers.\n\nI don't expect you to understand... you'll probably just end up like the others.  You'd best return to whoever sent you.  They might be worried.", sourceObjective = "Return to Koltira Deathweaver aboard Orgrim's Hammer.", completion = "There you are.  Nice work down in the valley.  The carnage was visible all the way up here.\n\nAre you okay?  You look like you've seen a ghost.", sourceObjectiveStatus = "unverified-source-field" }
quests[13349] = { id = 13349, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cradle of the Frostbrood", description = "We need to keep our momentum going.  Let's not give the Scourge forces any respite.\n\nSindragosa's Fall lies east just beyond the Valley of Lost Hope.  The Cult of the Damned operate there, under close supervision of the Lich King's undead vrykul lackeys.\n\nIt is a place of great power, possibly a blue dragonflight graveyard.  The feared frostbrood are raised there from the bones of blue dragons.\n\nAn attack there would have great impact on the enemy's access to frost wyrms.  Are you up to it, {name}?", sourceObjective = "Koltira Deathweaver aboard Orgrim's Hammer wants you to slay 5 Wyrm Reanimators, 8 Cultist Corrupters and 3 Vrykul Necrolords at Sindragosa's Fall.", progress = "Hail, {name}.", completion = "You've done well, {name}.  You might want to rest for a while.  You look a little pale.", sourceObjectiveStatus = "unverified-source-field" }
quests[13350] = { id = 13350, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Rest For The Wicked", description = "It's Alumeth... He's growing in power again. I can sense it. Again his underlings are channeling power to his soul.\n\nIf he's allowed to rest, their efforts will soon transform him into a mighty adversary.\n\nReturn to his chamber in the north portion of Aldur'thar. Combine his heart, skull, scepter and robes, then use his remains on the crystal there.\n\nHurry, {race}! Destroy him before he becomes any more powerful!", sourceObjective = "Thassarian, aboard the Skybreaker, wants you to defeat Alumeth the Ascended at Aldur'thar.", completion = "Alumeth has suffered a sound defeat, but I sense that his spirit still lingers...", sourceObjectiveStatus = "unverified-source-field" }
quests[13351] = { id = 13351, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sneak Preview", description = "Progress is being made. We have a promising array of tactics that should gain us control of the death gate. There will doubtlessly be many casualties, but in the end,  we should be able to prevail - barring any interference from the Alliance.\n\nOur next focus will be Aldur'thar, the gate of desolation. Fly down and become familiar with it and with the enemies posted there.\n\nWhen you return, I will have your missions prepared.", sourceObjective = "Koltira, aboard Orgrim's Hammer, wants you to fly down to the gate of desolation, visiting the south, central, north, and northwest regions of the gate.", progress = "Have you scouted the gate of desolation, {class}?", completion = "Well and good, {class}.\n\nNow that you've seen firsthand what we're up against, it's time to get to work...", sourceObjectiveStatus = "unverified-source-field" }
quests[13352] = { id = 13352, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drag and Drop", description = "The Cult of the Damned hold the gate of desolation, eh? No surprise there.\n\nTime to have a little fun. At the southern end of the gate, you mentioned there were new cultists being trained. They're almost certain to be holding a special item given to all initiates - an Orb of Illusion.\n\nThese artifacts are used to disguise a cult member, allowing them to gain safe passage, infiltrate, or simply blend in with an enemy.\n\nKill the fools until you find one, {class}, then use it on a subjugator.", sourceObjective = "Koltira, aboard Orgrim's Hammer, wants you to collect Orbs of Illusion from Bitter Initiates at Aldur'thar and use them on 3 Dark Subjugators there.", completion = "An effective tool, given the circumstances, wouldn't you say?\n\nThat one never gets old....", sourceObjectiveStatus = "unverified-source-field" }
quests[13353] = { id = 13353, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drag and Drop", description = "Looks like those initiates are increasing in number again. You know what to do...\n\nAt the southern portion of the gate, the new cultists are being trained. They're certain to be holding a special item given to all initiates - an Orb of Illusion.\n\nThese artifacts are used to disguise a cult member, allowing them to gain safe passage, infiltrate, or simply blend in with an enemy.\n\nSlay the fools until you find some, then use them on the subjugators there.", sourceObjective = "Koltira, aboard Orgrim's Hammer, wants you to collect Orbs of Illusion from Bitter Initiates at Aldur'thar and use them on 3 Dark Subjugators there.", progress = "Yes, {race}?", completion = "An effective tool, given the circumstances, wouldn't you say?\n\nThat one never gets old....", sourceObjectiveStatus = "unverified-source-field" }
quests[13354] = { id = 13354, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chain of Command", description = "Based on your report, and my knowledge of the Cult, they have an overseer managing the operation of each encampment on the gate.\n\nWhile taking their leaders down will only be a temporary setback, it will at least slow them down and keep them off-balance. And that, {race}, is a worthy enough goal for now.\n\nSeek out these overseers and return to me when they have been dispatched.", sourceObjective = "Koltira aboard Orgrim's Hammer wants you to go to Aldur'thar and defeat Overseer Faedris, Overseer Savryn, Overseer Veraj, and Overseer Jhaeqon.", completion = "Well done, {race}. But don't break your arm patting yourself on the back. They'll have those overseers replaced in no time...", sourceObjectiveStatus = "unverified-source-field" }
quests[13355] = { id = 13355, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cannot Reproduce", description = "I smell their cauldrons from here, but that's not plague they're cooking.\n\nPledges to the cult are forced to drink a concoction that steals their will and enslaves them forever to the Lich King.\n\nSome say the potion contains the twisted soul of a being who was tormented before being mercilessly slaughtered, but I've never been able to reproduce it...\n\nFill this flask with a sample from each of the three cauldrons in the northwest region of the gate and bring it to Chief Engineer Copperclaw.", sourceObjective = "Koltira aboard Orgrim's Hammer wants you to use the Partitioned Flask at each of the 3 Cultists' Cauldrons at Aldur'thar, then bring it to Chief Engineer Copperclaw.", progress = "Whatdya got there, {class}?", completion = "<Copperclaw pours the contents of the flask into his particle analyzer.>\n\nAhh... I know just the thing!", sourceObjectiveStatus = "unverified-source-field" }
quests[13356] = { id = 13356, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Retest Now", description = "This should do the trick!\n\nThose twisted hooligans are looking for souls to put in their crazy-juice? Then I say we help 'em out a bit!\n\nTake a swig of this - don't worry, I've diluted it plenty... Its only effect will be to detect any cultist's essence once you've defeated them.\n\nWhen you've collected a bunch of essences, throw the writhing mass of twisted souls into any of their cauldrons.\n\nLet's see how they like a taste of their own medicine!", sourceObjective = "Chief Engineer Copperclaw aboard Orgrim's Hammer wants you to throw a Writhing Mass into a cauldron at Aldur'thar.", completion = "Wahoo!\n\nThat'll teach 'em!", sourceObjectiveStatus = "unverified-source-field" }
quests[13357] = { id = 13357, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Retest Now", description = "Those twisted cultists are looking for souls to put in their crazy-juice? Then let's help 'em out a bit!\n\nTake a swig of this - don't worry, I've diluted it plenty... I'm almost positive that its only effect will be to detect any cultist's essence.\n\nOnce you've collected a bunch of 'em, throw the writhing mass of twisted souls in one of their cauldrons.\n\nLet's see how they like a taste of their own medicine!", sourceObjective = "Chief Engineer Copperclaw aboard Orgrim's Hammer wants you to throw a Writhing Mass into a cauldron at Aldur'thar.", completion = "Wahoo!\n\nThat'll teach 'em!", sourceObjectiveStatus = "unverified-source-field" }
quests[13358] = { id = 13358, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not a Bug", description = "Alright, <friend/missy>, time to plant a bug.\n\nRelax, it's not a bug exactly, but it'll serve our purposes.\n\nIn the northern portion of Aldur'thar, the cult's void summoners enslave demonic minions. Use this rod to siphon the dark matter from the corpses of these enslaved minions, and then use the cultists' summoning crystal to bring our little spy into being.\n\nUntil it is discovered, the messenger will serve as our eyes and ears, discreetly observing the actions of our enemy.", sourceObjective = "Koltira, aboard Orgrim's Hammer, wants you to collect 5 Dark Matters and summon a Dark Messenger at Aldur'thar.", completion = "You have done well, {class}.\n\nThe messenger has already turned up some valuable information.", sourceObjectiveStatus = "unverified-source-field" }
quests[13359] = { id = 13359, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where Dragons Fell", description = "A whole brood of blue dragons fell here.  And now, one by one, they're being raised by his servants.\n\nHe raised the biggest of them all himself.  Bring me some bone dust from the whelps and I'll show you exactly how he did it.", sourceObjective = "Matthias Lehner at Sindragosa's Fall wants you to obtain 6 Whelp Bone Dusts.", progress = "Did you get the dust, {name}?", completion = "Even the mighty wyrms had to heed his call.  How is a simple mortal like you going to resist him?", sourceObjectiveStatus = "unverified-source-field" }
quests[13360] = { id = 13360, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time for Answers", description = "You have a lot of questions, {name}.  You're the only one who can see me because you touched something that once belonged to him... don't you remember?\n\nYou don't know what it is?  Well I can't just tell you... that would make him really mad.  He's not just a prince anymore... he's the king!\n\nMeet me at the Court of Bones, north of Icecrown Citadel and you can see for yourself.", sourceObjective = "Speak to Matthias Lehner at the Court of Bones.", completion = "There you are.  I started to wonder whether you'd show up.", sourceObjectiveStatus = "unverified-source-field" }
quests[13361] = { id = 13361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hunter and the Prince", description = "Before the prince became a king, he fought many battles... but only one where he came close to dying.\n\nIt was fought right here.  After you let me show you what happened, you'll understand everything.\n\nFind a bloodstained stone and pick it up from the floor.  You'll see what happened.", sourceObjective = "Matthias Lehner in the Court of Bones wants you to look for a Bloodstained Stone and complete the Prince's Destiny.", progress = "Did you see, {name}?  Did you?", completion = "After that fight, the prince realized what was holding him back was that he was still human... he could still feel... he could still bleed.  He still had a heart.\n\nThe first thing he did when he became king was to rid of himself of it.  He threw it down the pit where we first met.  And you, {name}, were the first person to touch it since.", sourceObjectiveStatus = "unverified-source-field" }
quests[13362] = { id = 13362, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knowledge is a Terrible Burden", description = "Now you know what you're up against, {name}.  An opponent who no longer knows pain... remorse... or humanity.  An opponent who will do anything to get what he wants.\n\nThe heart was his weakness and now he knows you've found it.\n\nIf you're going to go back for it, you'd best bring help.  He will not leave it unguarded again.", sourceObjective = "Report back to Koltira aboard Orgrim's Hammer.", completion = "Little kid's ghost... Arthas's heart... you'd better slow down... you're making my head spin.", sourceObjectiveStatus = "unverified-source-field" }
quests[13363] = { id = 13363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Argent Aid", description = "There were rumors about the events you speak of among the death knights.  I always expected the story to be more... symbolic.\n\nWe must warn others, but we must be discreet.  As soon as the Lich King knows we're making our move, he'll move the location of the heart -- we'll never get a chance like this again.\n\nThe Horde and the Alliance have been infiltrated by the Cult of the Damned before.  The Ebon Blade operates too close to the Scourge.\n\nWe have to speak to Tirion Fordring and his Argent Crusade.", sourceObjective = "Speak to Highlord Tirion Fordring at the Crusader's Pinnacle.", completion = "Heavy words, {name}.  If it were somebody else saying them, I'd be likely to judge them insane.", sourceObjectiveStatus = "unverified-source-field" }
quests[13364] = { id = 13364, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tirion's Gambit", description = "Just this morning, my scouts informed me of a Cult of the Damned procession leaving from Icecrown Citadel to the Cathedral of Darkness, bearing an artifact.\n\nAnd now I learn that it might be Arthas's own heart... a thing containing the last bit of his remaining humanity.\n\nThis is a sign of the Light.  As long as such an artifact exists, there is a chance that Arthas Menethil can become a man again!\n\nMeet me at the cathedral's entrance.  Be sure to bring a cultist's hood -- we're going incognito.", sourceObjective = "Tirion Fordring, at the Crusader's Pinnacle, wants you to obtain and wear a Cultist Acolyte's Hood and meet him at the entrance of the Cathedral of Darkness, northwest of Icecrown Citadel.", progress = "Light be with you, {name}.", completion = "I do not view what we just went through as a failure, {name}... quite the opposite.\n\nBy allowing me to peer into his heart, you allowed me to confirm what I needed to know.  There is no Arthas Menethil anymore -- there is only the Lich King.", sourceObjectiveStatus = "unverified-source-field" }
quests[13365] = { id = 13365, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not a Bug", description = "The cultists have discovered the last messenger you summoned, {race}.\n\nWhile it was quite informative, it's important that we continue to monitor the cult's every move.\n\nUse this rod to siphon the dark matter from the corpses of enslaved minions at Aldur'thar. Then use their summoning crystal to bring another dark messenger into being.\n\nUntil it is discovered, the messenger will serve as our eyes and ears, discreetly observing the actions of our enemy.", sourceObjective = "Koltira, aboard Orgrim's Hammer, wants you to collect 5 Dark Matters and summon a Dark Messenger at Aldur'thar.", progress = "Yes, {class}?", completion = "Well done, friend.\n\nThe messenger is up and reporting in as we speak.", sourceObjectiveStatus = "unverified-source-field" }
quests[13366] = { id = 13366, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Need More Info", description = "The Cult of the Damned are notorious for concocting grandiose plans that in the end, rarely succeed. But something feels different this time....\n\nPerhaps it's the proximity to the Lich King that has their fervor heightened. Whatever it is, they appear to be more confident than ever. We must know what feeds this bravado and then find a way to strip them of it!\n\nI believe the key lies with their researchers. Find out what they're up to and report back to me with the details.", sourceObjective = "Koltira, aboard Orgrim's Hammer, wants you to collect the 3 pages of Cultists' Research from the Cult Researchers at Aldur'thar and use them to create the Cult of the Damned Thesis.", progress = "Have you discovered what their researchers are up to, {class}?", completion = "This is alarming, indeed....", sourceObjectiveStatus = "unverified-source-field" }
quests[13367] = { id = 13367, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Rest For The Wicked", description = "These fools have actually stumbled upon something that could pose a serious threat to our plans!\n\nThe leader of this particular sect, Alumeth, has ritualistically sacrificed himself and now his underlings are channeling power to his soul.\n\nIf he's allowed to rest, their efforts will soon transform him into a mighty adversary.\n\nCombine his heart, skull, scepter and robes from around their chamber and use his remains on the crystal there.\n\nHurry, {race}! Destroy him before he becomes any more powerful!", sourceObjective = "Koltira, aboard Orgrim's Hammer, wants you to slay Alumeth the Ascended at Aldur'thar.", completion = "Alumeth has suffered a sound defeat, but I sense that his spirit still lingers...", sourceObjectiveStatus = "unverified-source-field" }
quests[13368] = { id = 13368, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Rest For The Wicked", description = "It's Alumeth... He's growing in power again. I can sense it. Again his underlings are channeling power to his soul.\n\nIf he's allowed to rest, their efforts will soon transform him into a mighty adversary.\n\nReturn to his chamber in the north portion of Aldur'thar. Combine his heart, skull, scepter and robes, then use his remains on the crystal there.\n\nHurry, {race}! Destroy him while there's still time!", sourceObjective = "Koltira, aboard Orgrim's Hammer, wants you to slay Alumeth the Ascended at Aldur'thar.", progress = "Well, friend? Were you successful against Alumeth?", completion = "Alumeth has suffered a sound defeat, but I sense that his spirit still lingers...", sourceObjectiveStatus = "unverified-source-field" }
quests[13369] = { id = 13369, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fate, Up Against Your Will", description = "At the behest of Lady Proudmoore, I will allow a diplomatic mission to Orgrimmar to question the Horde's Warchief, Thrall. You will assist her in this journey and keep her safe from harm. Return to me with news from Orgrimmar.\n\nSpeak to Jaina when you are ready to leave.", sourceObjective = "Assist Lady Jaina Proudmoore in Orgrimmar. Speak to the Warchief of the Horde, Thrall, at Orgrimmar on the continent of Kalimdor.", completion = "The Horde does not want war, {race}. Listen well...", sourceObjectiveStatus = "unverified-source-field" }
quests[13370] = { id = 13370, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Royal Coup", description = "Your champion, Bolvar, died in defense of our world. The Horde is saddened by the loss of such a great hero, but the Horde was not responsible for the cowardly attacks made by Putress at the Wrath Gate. We have also lost mighty heroes because of this betrayal.\n\nTell your king that we will do everything in our power to bring the perpetrators of this cowardly act to justice. We will do all that we can to avoid conflict with the Alliance, but we will not hesitate to defend ourselves if provoked.", sourceObjective = "Use the portal in Grommash Hold to return to Stormwind Keep and deliver Thrall's message to King Varian Wrynn.", completion = "They have lost the Undercity? Then the time to strike is now. We will deal with Putress ourselves and retake the Ruins of Lordaeron for the Alliance!", sourceObjectiveStatus = "unverified-source-field" }
quests[13371] = { id = 13371, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Killing Time", description = "I sent Broll and Valeera to the Undercity before you left for Orgrimmar. In fact, they're now stationed outside the sewer entrance to the ruins, awaiting orders.\n\nLady Proudmoore will open a portal to our forces outside the Undercity. Go there and report to Broll. Jaina and I will be close behind.", sourceObjective = "Use the Portal to the Undercity inside Stormwind Keep to teleport to the Undercity. Report to Broll Bearmantle when you arrive at your destination.", completion = "Who are you supposed to be? Varian said he'd send heroes.", sourceObjectiveStatus = "unverified-source-field" }
quests[13372] = { id = 13372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Key to the Focusing Iris", description = "A potent thrumming of magical nature can be heard and felt emanating from the eye-shaped jewel dropped from Sapphiron's clutches. To mortal ears it is nearly painful to be in the presence of the stone.\n\nSurely such a powerful item of import can only be taken to the queen of the dragons, Alexstrasza the Life-Binder. Seek her counsel atop Wyrmrest Temple in the Dragonblight.", sourceObjective = "Deliver the Key to the Focusing Iris to Alexstrasza the Life-Binder atop Wyrmrest Temple in the Dragonblight.", progress = "{name}, you have come into contact with a key to the focusing iris! Do you have it upon your person?\n\n\n\nHow did you ever come into its possession? Oh, Sapphiron still had his?", completion = "These keys are held by the most ancient members of the blue dragonflight. Only they are entrusted with them by their master, Malygos.\n\nThis is the break that we've been waiting for to strike at the Aspect of Magic!\n\n<The queen of dragons studies you for a brief moment.>\n\nYou are not able to use the key as-is to access the Focusing Iris, but I can imbue you with a portion of my power; enough to enable you to use it to open the iris a fraction.\n\nIt will be enough to draw Malygos's ire!", sourceObjectiveStatus = "unverified-source-field" }
quests[13373] = { id = 13373, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fringe Science Benefits", description = "I installed our infra-green technology into commandeered bombers; it'll protect you on your first mission into enemy territory!  Speak with Rizzy Ratchwiggle to get a bomber, then fly into The Bombardment!\n\nYou'll have bombs and rockets and shields.  Keep the shields charged and use bombs on the ground Scourge at The Bombardment.  Come back after you hit your targets, and more work will await you.", sourceObjective = "Fringe Engineer Tezzla wants you to kill 40 Bombardment Infantry, 8 Bombardment Captains and 15 Gargoyle Ambushers.", progress = "You haven't reached your target quota, {name}.  Are the bombers too hard to handle?", completion = "Hah, you got them!  How did you like the bomber?  I hope you got the hang of it, because I have more missions for you...", sourceObjectiveStatus = "unverified-source-field" }
quests[13374] = { id = 13374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amped for Revolt!", description = "{name}, only our best pilots are given a mission like this, one deep, deep into enemy territory with only the power of infra-green technology to protect you!\n\nRequest another bomber from Rizzle, and this time fly it through the Valley of Lost Hope.  You have both air and ground targets on this mission, so keep your eyes open and your shields at full!\n\nGood luck!", sourceObjective = "Fringe Engineer Tezzla wants you to kill Bombardment Infantry, Gargoyle Ambushers, Frostbrood Sentries and Scourge War Machines.", sourceObjectiveStatus = "unverified-source-field" }
quests[13375] = { id = 13375, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Heroic Key to the Focusing Iris", description = "A potent thrumming of magical nature can be heard and felt emanating from the eye-shaped jewel dropped from Sapphiron's clutches. To mortal ears it is nearly painful to be in the presence of the stone.\n\nSurely such a powerful item of import can only be taken to the queen of the dragons, Alexstrasza the Life-Binder. Seek her counsel atop Wyrmrest Temple in the Dragonblight.", sourceObjective = "Deliver the Heroic Key to the Focusing Iris to Alexstrasza the Life-Binder atop Wyrmrest Temple in the Dragonblight.", progress = "{name}, you have come into contact with a key to the iris! Do you have it upon your person?\n\n\n\nHow did you ever come into its possession? Oh, Sapphiron still had his?", completion = "These keys are held by the most ancient members of the blue dragonflight. Only they are entrusted with them by their master, Malygos.\n\nThis is the break that we've been waiting for to strike at the Aspect of Magic!\n\n<The queen of dragons studies you for a brief moment.>\n\nYou are not able to use the key as-is to access the Focusing Iris, but I can imbue you with a portion of my power; enough to enable you to use it to open the iris a fraction.\n\nIt will be enough to draw Malygos's ire!", sourceObjectiveStatus = "unverified-source-field" }
quests[13376] = { id = 13376, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Total Ohmage: The Valley of Lost Hope!", description = "{name}, the struggle continues.  Lucky for us, we're stocked up on bombs and rockets!  Time for another bombing mission  --  this one's a long one, through the Bombardment and into the Valley of Lost Hope.  Head back out with an infra-green bomber and blow those Scourge into little scourge-lets!", sourceObjective = "Fringe Engineer Tezzla wants you to kill 50 Bombardment Infantry, 20 Gargoyle Ambushers, 12 Frostbrood Sentries and 12 Scourge War Machines.", progress = "What are you waiting for?  We have the hardware and the ordinance... we just need brave gunners like you to apply them.", completion = "Great work, {name}.  While you were out, I heard other gunners talking about you... I think you have a real future in air offense!", sourceObjectiveStatus = "unverified-source-field" }
quests[13377] = { id = 13377, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle For The Undercity", description = "Deep inside the bowels of the Undercity hides the assassin responsible for the deaths of Bolvar and our brave soldiers at the Wrath Gate.\n\nVarian has brought the full might of the Alliance with him to assist in the take down. Join him and Lady Proudmoore in the manhunt and earn your place among the greatest champions of the Alliance!\n\nSpeak to King Varian Wrynn when you are ready.", sourceObjective = "Assist King Varian Wrynn and Lady Jaina Proudmoore in bringing Grand Apothecary Putress to justice! Report to King Varian Wrynn should you succeed.", completion = "For too long have the Horde been left unchecked. We allowed their territories to prosper and in return for our generosity they plotted and planned our demise.\n\nPeace? Useless... It's gotten us nowhere. We have lost some of our greatest heroes to \"peace.\" Let us see what battle brings...\n\nReturn to Northrend, {name}. Conquer it for your king - FOR THE ALLIANCE!", sourceObjectiveStatus = "unverified-source-field" }
quests[13378] = { id = 13378, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chief Engineer Copperclaw", description = "Speak with Chief Engineer Copperclaw." }
quests[13379] = { id = 13379, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Green Technology", description = "Tezzla is the one you want to meet, yes she is... she mastered a new wavelength, infra-green, and used it to hide herself near the Scourge!  Near enough to bomb them!\n\nI'll give you infra-green vision so you can find her hiding above Aldur'thar, the Desolation Gate.  Go, go... I know she has work for brave heroes eager to blow up!  I mean... eager to blow up the Scourge!\n\nAnd {name}, the Alliance has stolen our technology and has their own hidden airport nearby.  Avoid the dome with the Alliance banners!", sourceObjective = "Speak with Fringe Engineer Tezzla.", completion = "Yes, yes!  You found me!  And just in time!", sourceObjectiveStatus = "unverified-source-field" }
quests[13380] = { id = 13380, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leading the Charge", description = "Infra-green technology allows us to stay hidden here, right over the Scourge's nose!  What's more, we installed infra-green in specially constructed bombers... but not to hide them, no!  We use infra-green tech to shield them!\n\nSpeak with Karen No and request a bomber.  Fly it over the Bombardment... use its shields and turret to protect yourself, and use the bomb launcher to hit Scourge targets.  Practice well, then return to me and I'll have an even more vital mission for you!", sourceObjective = "Kibli Killohertz wants you to kill 40 Bombardment Infantry, 8 Bombardment Captains and 15 Gargoyle Ambushers.", progress = "{name}, the bombers are difficult to use, but you must master them if we're to win our struggles against the Scourge.", completion = "I could hear your explosions from here, {name}.  How did the shields work?  Did they keep your bomber intact?\n\nI hope they did, because now I have more missions for you....", sourceObjectiveStatus = "unverified-source-field" }
quests[13381] = { id = 13381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Watts My Target", description = "Put on your lucky socks, {name}, and say your favorite prayers.  This next mission will test your wit and fortitude like a visit from the in-laws!\n\nRequest another bomber from Karen No.  Take it beyond The Bombardment and over the Valley of Lost Hope.  You have more targets this time, both on the land an in the air.  Keep your shields charged and your ammo loaded, {name}!  I'll see you when it's over.", sourceObjective = "Kibli Killohertz wants you to kill Bombardment Infantry, Gargoyle Ambushers, Frostbrood Sentries and Scourge War Machines.", sourceObjectiveStatus = "unverified-source-field" }
quests[13382] = { id = 13382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Putting the Hertz: The Valley of Lost Hope", description = "The fight goes on!  Your new orders arrived for a long-range bombing mission through the Bombardment and into the Valley of Lost Hope -- when you're ready, ask Karen for a bomber and pour those bombs and rockets onto the Scourge!", sourceObjective = "Kibli Killohertz wants you to kill 50 Bombardment Infantry, 20 Gargoyle Ambushers, 12 Frostbrood Sentries and 12 Scourge War Machines.", progress = "Keep at them, {name}.  The air battle won't win itself!", completion = "Welcome back, {name}.  How was the battle?  Exciting?  Take a rest for now.  But come back when you have fresh orders.\n\nFor the Alliance!", sourceObjectiveStatus = "unverified-source-field" }
quests[13383] = { id = 13383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Killohertz", description = "The goblins got lucky and found a new energy.  They call it infra-green, and I'll be a one-eyed ogre if those psychos didn't strike green gold.\n\nGo find Kibli Killohertz.  He's leading the reverse engineering efforts of infra-green, at a small, hidden Alliance airport above Aldur'thar, the Desolation Gate.  I'll give you infra-green vision to help you find it.  Go to the dome with our Alliance banners -- if you fly near the Horde airport then you'll be in a load of green trouble.", sourceObjective = "Chief Engineer Boltwrench wants you to find Kibli Killohertz at the hidden Alliance airport above Aldur'thar, the Desolation Gate.", completion = "Yes, yes, yes!  A thousand times, hello!", sourceObjectiveStatus = "unverified-source-field" }
quests[13384] = { id = 13384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Judgment at the Eye of Eternity", description = "Now that you have access to the focusing iris it's time to put that key to use.\n\nAs much as I would like to see Malygos brought back into the fold, that's just not going to happen at this point. With everything that's at stake, it is the judgment of the other Dragon Aspects that the Spell-Weaver needs to be put down.\n\n<Krasus says this last with a great deal of trepidation.>\n\n{name}, travel to the Eye of Eternity, confront Malygos and return with the Heart of Magic.", sourceObjective = "Krasus atop Wyrmrest Temple in the Dragonblight wants you to return with the Heart of Magic.\n\nThis quest is for the Normal mode, 10-person version of The Eye of Eternity.", progress = "Only Malygos carries the Heart of Magic. It is his most prized possession.", completion = "This is a very sad day, not only for dragonkind, but for all of the living creatures of Azeroth. We have lost one of our most thoughtful, intelligent and ancient friends. Magic is now without its guardian.\n\nLet us hope that this was a wise decision in the coming years, {name}. A storm is still brewing on the horizon and now we are without one of our most powerful defenders.", sourceObjectiveStatus = "unverified-source-field" }
quests[13385] = { id = 13385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroic Judgment at the Eye of Eternity", description = "Now that you have access to the focusing iris it's time to put that key to use.\n\nAs much as I would like to see Malygos brought back into the fold, that's just not going to happen at this point. With everything that's at stake, it is the judgment of the other Dragon Aspects that the Spell-Weaver needs to be put down.\n\n<Krasus says this last with a great deal of trepidation.>\n\n{name}, travel to the Eye of Eternity, confront Malygos and return with the Heart of Magic.", sourceObjective = "Krasus atop Wyrmrest Temple in the Dragonblight wants you to return with the Heart of Magic.\n\nThis quest can be completed in both 10-person and 25-person versions of The Eye of Eternity.", progress = "Only Malygos carries the Heart of Magic. It is his most prized possession.", completion = "This is a very sad day, not only for dragonkind, but for all of the living creatures of Azeroth. We have lost one of our most thoughtful, intelligent and ancient friends. Magic is now without its guardian.\n\nLet us hope that this was a wise decision in the coming years, {name}. A storm is still brewing on the horizon and now we are without one of our most powerful defenders.", sourceObjectiveStatus = "unverified-source-field" }
quests[13386] = { id = 13386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exploiting an Opening", description = "I've got an interesting assignment for you, {name}.  If you're up for a challenge, that is.\n\nWe've been tipped off about an opening below Icecrown Citadel.  Our engineers have studied the layout and have decided it's a structural weakness.\n\nWe've sent some men there along with some \"borrowed\" saronite bombs.  They're under Captain Kendall's command.\n\nWith a little help we could deal a huge blow to the forces of the Scourge.  What do you say, {name}?", sourceObjective = "Speak to Captain Kendall below Icecrown Citadel.", completion = "Hail, {name}.  Thassarian mentioned you'd be dropping by.  Any friend of Thassarian's is my friend.  Well, any living friend of Thassarian, that is...  He does keep odd company.", sourceObjectiveStatus = "unverified-source-field" }
quests[13387] = { id = 13387, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Securing the Perimeter", description = "The saronite bombs are in place, {name}.  We're only going to get one shot at this, however.  Let's make it count.\n\nWe need temporary control of the area for a safe detonation.  Let's try to put a dent in the Scourge's numbers.", sourceObjective = "Captain Kendall at Icecrown Citadel wants you to slay 10 Hulking Horrors.", progress = "For the Alliance!", completion = "You're as good as Thassarian said.  Good job!", sourceObjectiveStatus = "unverified-source-field" }
quests[13388] = { id = 13388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Set it Off!", description = "Things are looking good.  Let's do this.\n\nThe stack of bombs is right near the pit.  I'll start to evacuate the men.", sourceObjective = "Captain Kendall, below Icecrown Citadel, wants you to go to the nearby Saronite Bomb Stack to light the fuse.", completion = "These bombs look pretty potent.  They should at least put a dent in the surrounding structure.", sourceObjectiveStatus = "unverified-source-field" }
quests[13389] = { id = 13389, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Short Fuse", description = "As you light the fuse, you notice that it is consumed by fire far quicker than you would expect.\n\nThe bombs are about to go off and your best chance at surviving is to lean towards the pit and hope the fall doesn't kill you.", sourceObjective = "Look for clues wherever the fall takes you.", completion = "This pulsing object is covered in a thick layer of ice.  It shimmers strangely beneath the water.", sourceObjectiveStatus = "unverified-source-field" }
quests[13390] = { id = 13390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Voice in the Dark", description = "The object is not a crystal at all, but some form of organ, encased in ice.\n\nAs you touch it, your hand reels in horrible pain.  You feel as if your hand has been cut, yet there is no visible wound.\n\nAs you collect your thoughts, you hear a young boy's voice nearby.\n\n\"You really shouldn't have done that.\"", sourceObjective = "Investigate the nearby voice in Naz'anak, the Forgotten Depths.", completion = "I saw him get rid of it, you know?  He threw it all the way down here.\n\nSaid he wouldn't need it anymore.  Said it made him weak.", sourceObjectiveStatus = "unverified-source-field" }
quests[13391] = { id = 13391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time to Hide", description = "You shouldn't have touched it.  But now that you did, he's going to come looking for you.\n\nAnd he'll find you.  Unless you hide yourself from him.\n\nBring me blood from the faceless ones if you want to live!", sourceObjective = "Matthias Lehner wants you to obtain 3 Faceless One's Blood.", progress = "Did you get the blood?", completion = "What are you waiting for?  You have to rub it on you!\n\nQuick!  Or he'll see you!", sourceObjectiveStatus = "unverified-source-field" }
quests[13392] = { id = 13392, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Surface", description = "You should leave now.  You'll find a portal behind me.  It'll take you to the surface.\n\nWe'll meet again.  He'll be looking for you.\n\nIt's only a matter of time until he finds you.", sourceObjective = "Return to Thassarian aboard the Skybreaker.", completion = "It's you, {name}!  We thought you were a goner.\n\nThat explosion of yours put quite a bit of hurt on the Scourge.  Nearly took Captain's Kendall's eyebrows off in the process...", sourceObjectiveStatus = "unverified-source-field" }
quests[13393] = { id = 13393, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Field Repairs", description = "All right.  Let's not celebrate just yet.  We need to capitalize on the momentum we've gathered with our little bombing mission.\n\nWe've spotted a workable Horde demolisher-class catapult in the field below.  The geist seem to be taking it apart.\n\nIf you can put it back together, we'll be able to do some serious damage to the Scourge's armies in the Valley.\n\nSure, you'll be a little outnumbered, but I've a lot of faith in you!", sourceObjective = "Thassarian, aboard the Skybreaker, wants you to collect 5 Demolisher Parts from the Scavenging Geists and take them to the Wrecked Demolisher in the Valley of Lost Hope.", progress = "The demolisher has suffered much damage.", completion = "The demolisher has seen better days, but the structure hasn't suffered any permanent damage.  The parts you obtained should be enough to get it running again, at least temporarily.", sourceObjectiveStatus = "unverified-source-field" }
quests[13394] = { id = 13394, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Do Your Worst", description = "You're going to use this machine against the Scourge?  You're not going to win against them like that.\n\nYou can destroy hundreds... even thousands of them.  But you won't win.  Not out here.\n\nWhen you're done playing with your machine, meet me to the north.  There is an old army encampment.  What I will show you will teach you a little bit about who you're up against.", sourceObjective = "Use the Refurbished Demolisher to destroy 150 Decomposed Ghouls, 20 Frostskull Mages and 2 Bone Giants in the Valley of Lost Hope. Speak to Matthias Lehner at the First Legion Forward Camp when you've completed this task.", progress = "Are you done playing with your war machines?", completion = "You see?  You killed your fair share, but for every one you destroyed, another rose from the dirt to take its place.\n\nYou don't know what you're up against, {name}.  Let me show you.", sourceObjectiveStatus = "unverified-source-field" }
quests[13395] = { id = 13395, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Army of the Damned", description = "You probably think you're quite strong -- fighting these undead and crushing their bones beneath your war machines.\n\nThat is nothing compared to the strength it took to create them.\n\nI saw the prince do it himself.  I can show you how it happened... if you'd like.", sourceObjective = "Matthias Lehner at the First Legion Forward Camp wants you to raise an army of 100 Ghoulish Minions.", completion = "The prince's true power wasn't his ability to make armies out of corpses... that was easy.\n\nBut killing his own men, with whom he'd shared many battles... the prince's true power was his ability to do what had to be done.", sourceObjectiveStatus = "unverified-source-field" }
quests[13396] = { id = 13396, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Futility", description = "Do you see now?  Sending your men against the prince's armies just swells their numbers.\n\nI don't expect you to understand... you'll probably just end up like the others.  You'd best return to whoever sent you.  They might be worried.", sourceObjective = "Return to Thassarian aboard the Skybreaker.", completion = "Nice shooting, {name}.  The Scourge never had a chance.\n\nAre you feeling okay?  You look like you've seen a ghost.  Not that it would be an unusual thing around these parts, now that I think about it.", sourceObjectiveStatus = "unverified-source-field" }
quests[13397] = { id = 13397, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sindragosa's Fall", description = "You're a real star, {name}.  See, when I give one of these other soldiers an assignment, the odds of them getting it done are about fifty-fifty.  The odds of them coming back... well, slightly worse.\n\nBut with you, it's always a guaranteed thing.  Like gnomish clockwork!\n\nAnyway, I have another one for you.  Sindragosa's Fall, east of the valley.  There is some serious cultist activity, including and not limited to, the raising of frost wyrms.  I need you to go kick their teeth in.\n\nI hate cultists.", sourceObjective = "Thassarian aboard the Skybreaker wants you to slay 5 Wyrm Reanimators, 8 Cultist Corrupters and 3 Vrykul Necrolords at Sindragosa's Fall.", completion = "Nice job, {name}.  You make the rest of us look bad!", sourceObjectiveStatus = "unverified-source-field" }
quests[13398] = { id = 13398, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where Dragons Fell", description = "A whole brood of blue dragons fell here.  And now, one by one, they're being raised by his servants.\n\nHe raised the biggest of them all himself.  Bring me some bone dust from the whelps and I'll show you exactly how he did it.", sourceObjective = "Matthias Lehner at Sindragosa's Fall wants you to obtain 6 Whelp Bone Dusts.", progress = "Did you get the dust, {name}?", completion = "Even the mighty wyrms had to heed his call.  How is a simple mortal like you going to resist him?", sourceObjectiveStatus = "unverified-source-field" }
quests[13399] = { id = 13399, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time for Answers", description = "You have a lot of questions, {name}.  You're the only one who can see me because you touched something that once belonged to him... don't you remember?\n\nYou don't know what it is?  Well I can't just tell you... that would make him really mad.  He's not just a prince anymore... he's the king!\n\nMeet me at the Court of Bones, north of Icecrown Citadel and you can see for yourself.", sourceObjective = "Speak to Matthias Lehner at the Court of Bones.", completion = "There you are.  I started to wonder whether you'd show up.", sourceObjectiveStatus = "unverified-source-field" }
quests[13400] = { id = 13400, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hunter and the Prince", description = "Before the prince became a king, he fought many battles... but only one where he came close to dying.\n\nIt was fought right here.  After you let me show you what happened, you'll understand everything.\n\nFind a bloodstained stone and pick it up from the floor.  You'll see what happened.", sourceObjective = "Matthias Lehner in the Court of Bones wants you to look for a Bloodstained Stone and complete the Prince's Destiny.", progress = "Did you see, {name}?  Did you?", completion = "After that fight, the prince realized what was holding him back was that he was still {race}... he could still feel... he could still bleed.  He still had a heart.\n\nThe first thing he did when he became king was to rid of himself of it.  He threw it down the pit where we first met.  And you, {name}, were the first person to touch it since.", sourceObjectiveStatus = "unverified-source-field" }
quests[13401] = { id = 13401, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knowledge is a Terrible Burden", description = "Now you know what you're up against, {name}.  An opponent who no longer knows pain... remorse... or humanity.  An opponent who will do anything to get what he wants.\n\nThe heart was his weakness and now he knows you've found it.\n\nIf you're going to go back for it, you'd best bring help.  He will not leave it unguarded again.", sourceObjective = "Report back to Thassarian aboard the Skybreaker.", completion = "Slow down, {name}.  Why don't you start again... from the beginning?", sourceObjectiveStatus = "unverified-source-field" }
quests[13402] = { id = 13402, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tirion's Help", description = "It's not the first time I've heard that story about Arthas and his heart... always thought it was some made-up tale to impress the rank and file.\n\nWe must act on this information immediately.  Unfortunately, we must do so in secret.\n\nArthas's agents are everywhere and if he finds out, our plan is dead in the water.\n\nWe need to take this to the Argent Crusade.  Every single paladin in that order was hand-picked by Tirion himself.  If there's anyone free of cultist infiltration, it's those guys.", sourceObjective = "Speak to Highlord Tirion Fordring at the Crusader's Pinnacle.", completion = "Heavy words, {name}.  If it were somebody else saying them, I'd be likely to judge them insane.", sourceObjectiveStatus = "unverified-source-field" }
quests[13403] = { id = 13403, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tirion's Gambit", description = "Just this morning, my scouts informed me of a Cult of the Damned procession leaving from Icecrown Citadel to the Cathedral of Darkness, bearing an artifact.\n\nAnd now I learn that it might be Arthas's own heart... a thing containing the last bit of his remaining humanity.\n\nThis is a sign of the Light.  As long as such an artifact exists, there is a chance that Arthas Menethil can become a man again!\n\nMeet me at the cathedral's entrance.  Be sure to bring a cultist's hood -- we're going incognito.", sourceObjective = "Tirion Fordring, at the Crusader's Pinnacle, wants you to obtain and wear a Cultist Acolyte's Hood and meet him at the entrance of the Cathedral of Darkness, northwest of Icecrown Citadel.", progress = "Light be with you, {name}.", completion = "I do not view what we just went through as a failure, {name}... quite the opposite.\n\nBy allowing me to peer into his heart, you allowed me to confirm what I needed to know.  There is no Arthas Menethil anymore -- there is only the Lich King.", sourceObjectiveStatus = "unverified-source-field" }
quests[13404] = { id = 13404, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Static Shock Troops: the Bombardment", description = "This is a short-ranged mission, over The Bombardment.  A good warm up.  Ready?", sourceObjective = "Kibli Killohertz wants you to kill 50 Bombardment Infantry, 10 Bombardment Captains and 20 Gargoyle Ambushers.", progress = "Keep at the, {name}.  The air battle won't win itself!", completion = "Welcome back, {name}.  A short mission, but invigorating, yes?  Take a rest for now.  But come back when you have fresh orders.", sourceObjectiveStatus = "unverified-source-field" }
quests[13405] = { id = 13405, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Strand of the Ancients", description = "The fight in Northrend is not only against the armies of the Lich King, but also against those of the Horde.\n\nA powerful titan relic has been found in the Strand of the Ancients.  As you might know, we dwarves have been custodians of such artifacts for years and as such we're their rightful keepers.\n\nIn this case, the Horde has developed a keen interest in pilfering the relic from the titan ruins.  They're certain to use it as a weapon against us; we must do whatever we can to stop them.", sourceObjective = "Win a Strand of the Ancients battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath.", completion = "Excellent job, {name}!  With your help the Strand of the Ancients will be under complete Alliance control.", sourceObjectiveStatus = "unverified-source-field" }
quests[13406] = { id = 13406, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riding the Wavelength: The Bombardment", description = "Ready to warm up with a short bombing mission?  You have your orders, and we have our bombers stocked and ready.", sourceObjective = "Fringe Engineer Tezzla wants you to kill 50 Bombardment Infantry, 10 Bombardment Captains and 20 Gargoyle Ambushers.", progress = "You haven't reached your target quota, {name}.  Get out there and blow stuff up!", completion = "Hah, you got them!  I could hear their Scourge parts clatter off the mountain walls.  Good work.  We'll have more for you soon...", sourceObjectiveStatus = "unverified-source-field" }
quests[13407] = { id = 13407, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Strand of the Ancients", description = "Just because we march into Northrend to smash the Scourge, doesn't mean we get to take a break from crushing the Alliance.\n\nThose Explorers' League dwarves have found the location of a powerful titan relic and we'll be damned if we let the Alliance take control of it.\n\nGo, {name}, and destroy our enemies.  Make them see that no matter where we meet, they remain our sworn enemies.", sourceObjective = "Win a Strand of the Ancients battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran, or Shattrath.", progress = "You're back!  Were you victorious, {name}?", completion = "You bring great honor to us, {name}!  The Alliance weaklings must be crushed under the heel of the mighty Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[13408] = { id = 13408, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hellfire Fortifications", description = "The Hellfire Citadel wages constant battles with our forces.  We are holding our own so far, but we can't yet launch a real offensive against them.  To do that, we need forward staging areas.\n\nOur scouts identified three fortifications near Hellfire Citadel.  We want you to help secure these forts.  Capture each fort, and then report back to me.\n\nMay fortune shine upon you in the conflicts ahead, {name}, for you will no doubt clash with Horde forces eager to gain these same fortifications.", sourceObjective = "Capture the Overlook, the Stadium and Broken Hill, then return to Warrant Officer Tracy Proudwell in Honor Hold in Hellfire Peninsula.", progress = "{name}, return to me when you have aided in the capture of each of the forts!", completion = "Well done, {name}.  Your actions in the field are instrumental in our battle for Hellfire Peninsula.", sourceObjectiveStatus = "unverified-source-field" }
quests[13409] = { id = 13409, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hellfire Fortifications", description = "The fel orcs of Hellfire Citadel must be scoured from our birthland!  To attack them, we must first secure forward staging points near the Citadel.\n\nOur outrunners found three fortifications that will suit this purpose, but the Alliance has the same idea and even now sends forces to take them!\n\nWe want you to stop the Alliance and capture these forts.  Aid in the capture of each fort and then return to me.\n\nFor the Horde!", sourceObjective = "Capture the Overlook, the Stadium and Broken Hill, then return to Battlecryer Blackeye in Thrallmar.", progress = "Return to me after you have helped capture each fort!", completion = "Nice work, {name}.  I could almost hear the battles waged at those forts.  I wish I was there to see them!", sourceObjectiveStatus = "unverified-source-field" }
quests[13410] = { id = 13410, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hellfire Fortifications", description = "The Hellfire Citadel wages constant battles with our forces.  We are holding our own so far, but we can't yet launch a real offensive against them.  To do that, we need forward staging areas.\n\nOur scouts identified three fortifications near Hellfire Citadel.  We want you to help secure these forts.  Capture each fort, and then report back to me.\n\nMay fortune shine upon you in the conflicts ahead, {name}, for you will no doubt clash with Horde forces eager to gain these same fortifications.", sourceObjective = "Capture the Overlook, the Stadium and Broken Hill, then return to Warrant Officer Tracy Proudwell in Honor Hold in Hellfire Peninsula.", completion = "Well done, {name}.  Your actions in the field are instrumental in our battle for Hellfire Peninsula.", sourceObjectiveStatus = "unverified-source-field" }
quests[13411] = { id = 13411, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hellfire Fortifications", description = "The fel orcs of Hellfire Citadel must be scoured from our birthland!  To attack them, we must first secure forward staging points near the Citadel.\n\nOur outrunners found three fortifications that will suit this purpose, but the Alliance has the same idea and even now sends forces to take them!\n\nWe want you to stop the Alliance and capture these forts.  Aid in the capture of each fort and then return to me.\n\nFor the Horde!", sourceObjective = "Capture the Overlook, the Stadium and Broken Hill, then return to Battlecryer Blackeye in Thrallmar.", progress = "Return to me after you have helped capture each fort!", completion = "Nice work, {name}.  I could almost hear the battles waged at those forts.  I wish I was there to see them!", sourceObjectiveStatus = "unverified-source-field" }
quests[13412] = { id = 13412, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corastrasza", description = "Greetings, {class}. Might I impose on you for a favor?\n\nCorastrasza is the sister of Raelorasz - the red dragon in charge of our outpost here. Against his will, she has ascended to one of the upper rings of the Nexus to observe some frighteningly powerful blue drakes.\n\nThough he will never say it, he worries about her, and would welcome any news of her well-being.\n\nPlease seek her out. Ask her to put her pride aside and send word to her brother.", sourceObjective = "Librarian Serrah wants you to speak to Corastrasza in Coldarra.", completion = "It's quite presumptuous of you to interfere in the personal affairs of a dragon, don't you think, {race}?\n\nThat aside, it would be wrong of me not to let my brother know that I am well. You may tell your meddling friend that I will keep my brother abreast of my actions.", sourceObjectiveStatus = "unverified-source-field" }
quests[13413] = { id = 13413, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aces High!", description = "You possess the courage to draw so near to Malygos' lair, mortal? Or is it simply ignorance? Soon we shall know....\n\nI am a seasoned trainer of the graceful drakes of the red dragonflight. My business here is to study the enemy and teach my precious pets the tactics that will be most effective when we face the master of the blues.\n\nTo demonstrate your nerve and ability, I will allow you to ride one of my drakes against the enemy's minions.\n\nThe opportunity is yours for the asking...", sourceObjective = "Corastrasza on the upper ring of the Nexus in Coldarra wants you to ride her drake and kill 5 Scalesworn Elites.", progress = "Well, mortal, what do you think of my pets?", completion = "My drake tells me that with practice, you might become a capable combatant.\n\nVery well, then. In the interest of our war on Malygos, I shall allow you to practice with my pets at your leisure.\n\nMake ready, {race}, for he is a fierce and unforgiving opponent.", sourceObjectiveStatus = "unverified-source-field" }
quests[13414] = { id = 13414, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aces High!", description = "Again we meet, {race}. I confess, your presence is beginning to grow on me.\n\nAm I correct in assuming that you've come to hone your aerial combat skills?\n\nAs always, my pets stand ready to bring fiery destruction to the enemy.\n\nSpeak, and they shall be at your disposal.", sourceObjective = "Corastrasza on the upper ring of the Nexus in Coldarra wants you to ride her drake and kill 5 Scalesworn Elites.", progress = "Yes, {race}?", completion = "I noticed some improvement today, {class}. At moments, it was as if you were one with the drake.\n\nYou are welcome to practice with my precious pets at your leisure.", sourceObjectiveStatus = "unverified-source-field" }
quests[13415] = { id = 13415, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Library Console", description = "Norgannon's shell is within our reach, {name}. Take the inventor's disk into the library's interior. There should be a console there that you can activate with the disk. I imagine Mimir stored more there than just Norgannon's shell. There are probably enough schematics stored there to keep Ironforge's engineers occupied for years!\n\nAnyway, use the disk to recover the shell. Hopefully, Mimir hasn't decided to put any more obstacles in our way.", sourceObjective = "Take the Inventor's Disk to the Inventor's Library Console inside the Inventor's Library.", progress = "The console appears to have an opening for the inventor's disk.", completion = "<You insert the disk into the console. Suddenly, lights on its surface illuminate and a mechanical voice speaks.>\n\nInventor's disk authenticated. Welcome back, Keeper Mimir.", sourceObjectiveStatus = "unverified-source-field" }
quests[13416] = { id = 13416, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Library Console", description = "Norgannon's shell is within our reach, {name}. Take the inventor's disk into the library's interior. There should be a console there that you can activate with the disk. I imagine Mimir stored more there than just Norgannon's shell. There are probably enough schematics stored there to keep Ironforge's engineers occupied for years!\n\nAnyway, bring the disk to the console. Hopefully, Mimir hasn't decided to put any more obstacles in our way.", sourceObjective = "Take the Inventor's Disk to the Inventor's Library Console inside the Inventor's Library.", progress = "The console appears to have an opening for the inventor's disk.", completion = "<You insert the disk into the console. Suddenly, lights on its surface illuminate and a mechanical voice speaks.>\n\nInventor's disk authenticated. Welcome back, Keeper Mimir.", sourceObjectiveStatus = "unverified-source-field" }
quests[13417] = { id = 13417, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Brothers Bronzebeard", description = "That does it! We finally have the keystone... It's beautiful! I've been around the world more than once, but this thing's got me all jittery with excitement again. I suppose now's not the time to stop and admire though, we need to get the heck out of here.\n\nHop on my flying machine and help keep us covered from those iron dwarves on the way out!You will be able to choose one of these rewards:", sourceObjective = "Accompany Brann Bronzebeard and his flying machine to Frosthold.", sourceObjectiveStatus = "unverified-source-field" }
quests[13418] = { id = 13418, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preparations for War", description = "You there!\n\nYou look like you have some wits about you. We could use some more able bodies in Icecrown.\n\nYou may have heard rumors of our failure in assaulting the glacier from the ground, but let me set those concerns to rest. We're now mounting our assault from one of the most advanced pieces of engineering known to Azeroth, the Skybreaker. The Horde don't stand a chance, and neither does Arthas.\n\nSpeak to me when you're ready to depart.", sourceObjective = "Speak to Officer Van Rossem to secure passage to the Skybreaker in Icecrown, and then report to High Captain Justin Bartlett.", completion = "Welcome to the Skybreaker.\n\nFrom here we are laying our groundwork for the assault on Arthas. There's a lot of work to be done, but before we can get into the real meat of it, we want to make sure that the Argent Crusade is adequately reinforced - we're going to need their help later.\n\nIf you have not already, speak to Absalan the Pious on the main deck.", sourceObjectiveStatus = "unverified-source-field" }
quests[13419] = { id = 13419, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preparations for War", description = "You there!\n\nYou look like you have some wits about you. We could use some more able bodies in Icecrown.\n\nThe Alliance scum rushed into Icecrown ahead of us, unprepared, and got just what they deserved for their impatience. We took our time, we made ready, and soon we will mount a true assault from one of the most advanced pieces of engineering known to Azeroth - Orgrim's Hammer. The Alliance don't stand a chance, and neither does Arthas.\n\nSpeak to me when you're ready to depart and lend a hand.", sourceObjective = "Speak to Sky-Reaver Klum to secure passage to Orgrim's Hammer in Icecrown, and then report to Sky-Reaver Korm Blackscar.", completion = "Welcome to Orgrim's Hammer.\n\nFrom here we are laying our groundwork for the assault on Arthas. There's a lot of preparation to be done, but before we can get into the real meat of it, we want to make sure that the Argent Crusade is adequately reinforced - we're going to need their help later.\n\nIf you have not already, speak to Brother Keltan on the main deck.", sourceObjectiveStatus = "unverified-source-field" }
quests[13420] = { id = 13420, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Everfrost", description = "This piece of ice has been submitted to immense pressures and exposed to natural magics from deep beneath the world's surface. In combination, these effects have yielded an ice that will never melt.\n\nKnowing little of these things, you resolve to bring the sample back to Dun Niffelem. Someone there is bound to be familiar with its properties.", sourceObjective = "You are to return to Dun Niffelem and ask Calder about the piece of Everfrost.\n\nProvided item:", completion = "<The reflection of the everfrost sparkles in Calder's eye as he holds it aloft.>\n\nAhh, everfrost. The symbol of the heart of our people...\n\nEverfrost was once plentiful in this region. Over the ages, though, the jormungar have devoured nearly all of it. It is now very rare and very precious to my people.\n\nAs you roam these lands, keep a lookout for more pieces of everfrost. Return to me with any that you find and we will be most grateful.", sourceObjectiveStatus = "unverified-source-field" }
quests[13421] = { id = 13421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Remember Everfrost!", progress = "Have you discovered any more everfrost, little {race}?", completion = "Well done, little {class}.\n\nEverfrost was once plentiful in this region. Over the ages, though, the jormungar devoured nearly all of it. It is now very rare and very precious to my people.\n\nAs you roam these lands, keep a lookout for more pieces of everfrost. Return to me with any that you find and we will be most grateful." }
quests[13422] = { id = 13422, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maintaining Discipline", description = "You've succeeded where others have failed.  Yet you cannot rest on your laurels.\n\nYou must show others what strength and commitment really mean.\n\nThe male insubordinates inside the Forlorn Mine need to be disciplined once again.  Show them sister... show them what it means to disobey us.", sourceObjective = "Gretta the Arbiter in Brunnhildar Village wants you to use the Disciplining Rod on 6 Exhausted Vrykul inside the Forlorn Mine.", completion = "You continue to lead by example.  We look up to you, sister.", sourceObjectiveStatus = "unverified-source-field" }
quests[13423] = { id = 13423, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defending Your Title", description = "Everyone's impressed by your performance, sister.  But do not let your guard down -- every new challenger with delusions of grandeur is going to come out swinging for your title of Hyldskvinnar.\n\nShow these upstarts what you're made of.", sourceObjective = "Gretta the Arbiter in Brunnhildar Village wants you to defeat 6 Victorious Challengers.", progress = "Your power humbles us, sister.", completion = "You continue to prove yourself worthy.  We are honored by your presence.", sourceObjectiveStatus = "unverified-source-field" }
quests[13424] = { id = 13424, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to the Pit", description = "To truly stay in your best riding shape you'll want to test yourself against the other Hyldnir every day.\n\nHead back into the Pit of the Fang and show them what you're capable of.  They'll appreciate suffering defeat to one as skilled as yourself.", sourceObjective = "Gretta the Arbiter, in Brunnhildar Village, wants you to use the Reins of the Warbear Matriarch inside the Pit of the Fang and defeat 6 Hyldsmeet Warbears.", completion = "You continue to demonstrate your prowess.  Your sisters have not lost their respect for you.", sourceObjectiveStatus = "unverified-source-field" }
quests[13425] = { id = 13425, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Aberrations Must Die", description = "It is not enough to demonstrate your prowess among your peers.  You must also fight our enemies, dear sister.\n\nThe Valkyrion traitors continue to mock our noble drake-riding traditions by rearing plagued proto-drakes.\n\nSeize the frost oil they wield and use it to freeze their abominable plagued eggs.", sourceObjective = "Gretta the Arbiter in Brunnhildar Village wants you to go to Valkyrion and obtain Vials of Frost Oil from the Valkyrion Aspirants. Use the Vials of Frost Oil to destroy 30 Plagued Proto-Drake Eggs.", progress = "Did you destroy the blighted eggs?", completion = "A leader in more ways than one.  We thank you, sister.", sourceObjectiveStatus = "unverified-source-field" }
quests[13426] = { id = 13426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Xarantaur, the Witness", description = "It seems we're not the only visitors to this area. A courier relayed a message from a tauren named Xarantaur, who said he was visiting a taunka village called Camp Tunka'lo. The note was somewhat cryptic, but it seems this Xarantaur has come to Storm Peaks to learn the history of a taunka legend.\n\nMeet up with him, {name}. See if what he knows can help us in any way. From his description, Camp Tunka'lo is far to the east, beyond the Terrace of the Makers and north of Dun Niffelem.", sourceObjective = "Speak with Xarantaur at Camp Tunka'lo.", completion = "So Boktar received my note? That's excellent news. I doubted the taunka longrummer who carried it would reach anyone.", sourceObjectiveStatus = "unverified-source-field" }
quests[13427] = { id = 13427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Alterac Valley", description = "The reality of fighting on multiple fronts, <lad/lass>, is that we cannot spread our forces too thin or we risk losing it all!\n\nCritical troop deployments are necessary on a day by day basis.  Today it is the battle for Alterac Valley that's in most need of brave combatants.\n\nGo now, {name}, and aid the Stormpike Expedition.  We cannot allow the Frostwolf Clan to get away with the violence they've inflicted on our brethren!", sourceObjective = "Win an Alterac Valley battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran or Shattrath.", progress = "Tell me, {name}.  What news do you bring from the front?", completion = "Just what I wanted to hear!  A victory in Alterac Valley - even a temporary one - is crucial to our overall strategy against the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[13428] = { id = 13428, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Alterac Valley", description = "We've recently come extremely close to driving the Stormpike invaders from Alterac Valley.  As a result we're redirecting all our reinforcements to aid the Frostwolf Clan.\n\nA decisive victory there would free up the resources we need to crush the Alliance scum on all the other battlefronts.\n\nGo, {name}.  Earn great honor by heeding the call of the brave Frostwolf warriors.", sourceObjective = "Win an Alterac Valley battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran or Shattrath.", progress = "You're back!  Do you bring news of victory?", completion = "There is no greater honor than driving invaders from Horde territories.  We salute your great courage in aiding our forces today!", sourceObjectiveStatus = "unverified-source-field" }
quests[13429] = { id = 13429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Distraction for Akama", description = "<Xi'ri pulses with lights as the Aldor and Scryer forces around him respond to his orders.  Xi'ri's army is ready to push Illidan's forces back and create a distraction for Akama.  The naaru awaits your request to begin the attack.>", sourceObjective = "Ensure that Akama and Maiev enter the Black Temple in Shadowmoon Valley after Xi'ri's forces create a distraction.", sourceObjectiveStatus = "unverified-source-field" }
quests[13430] = { id = 13430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trial of the Naaru: Magtheridon", description = "Four trials you must pass before you are deemed worthy by the naaru.\n\nOnly one obstacle remains, mortal. Gather an army and travel to the lair of Magtheridon, deep inside Hellfire Citadel. Battle your way to the heart of the chamber and destroy the foul corrupter!", sourceObjective = "A'dal in Shattrath City wants you to slay Magtheridon.", completion = "You have proven yourself as a being of great power. The naaru approve...", sourceObjectiveStatus = "unverified-source-field" }
quests[13431] = { id = 13431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cudgel of Kar'desh", description = "Bring me the elemental signets that the cudgel requires!\n\nThe earthen signet is held by Gruul the Dragonkiller. Gruul can be found inside his lair in the Blade's Edge Mountains.\n\nThe second signet is the blazing heart of a creature known as Nightbane. This mythical beast is said to reside in the hallowed halls of the prophet, Medivh.\n\nMake haste!", sourceObjective = "Skar'this the Heretic in the heroic Slave Pens of Coilfang Reservoir wants you to bring him the Earthen Signet and the Blazing Signet.", progress = "With the cudgel reformed, I shall break free of my bonds and return to Serpentshrine to exact vengeance on Vashj and her minions!", completion = "At last!\n\nWith these bonds broken and the cudgel in my possession I shall send  the sea witch back to the icy depths...", sourceObjectiveStatus = "unverified-source-field" }
quests[13432] = { id = 13432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Vials of Eternity", description = "Seven vials were drawn from the Well of Eternity by Illidan.  He poured three into the lake on top of Mount Hyjal and a second Well of Eternity was created.  For years the rest were believed lost.\n\nWith the opening of the Dark Portal, we've come to know that he gave one each to his lieutenants Kael'thas and Vashj.  Retrieve what remains of them; we will need them as foci to open a gateway to any events tied to Mount Hyjal, recent or ancient.  The outcome of the Battle of Mount Hyjal must be preserved.", sourceObjective = "Soridormi at Caverns of Time wants you to retrieve Vashj's Vial Remnant from Lady Vashj at Coilfang Reservoir and Kael's Vial Remnant from Kael'thas Sunstrider at Tempest Keep.", progress = "I've asked the impossible of you, yet I expect you to succeed.  Much depends on it.", completion = "The power contained even in this small amount of water from the Well of Eternity is incredible.\n\nI can see clearly into every moment in time linked to Hyjal... the creation of the second Well of Eternity, Illidan's imprisonment, the enchantment of the World Tree and... yes!  The Battle of Mount Hyjal.\n\nWe must make haste, the timeline is not safe.", sourceObjectiveStatus = "unverified-source-field" }
quests[13433] = { id = 13433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket", sourceObjective = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!", sourceObjectiveStatus = "unverified-source-field" }
