quests[13500] = { id = 13500, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor the Flame", sourceObjective = "Honor the Zul'Drak flame.", sourceObjectiveStatus = "unverified-source-field" }
quests[13501] = { id = 13501, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket", sourceObjective = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!", sourceObjectiveStatus = "unverified-source-field" }
quests[13502] = { id = 13502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tisket, a Tasket, a Noblegarden Basket", description = "Here... take this Egg Basket and go hunting for Brightly Colored Eggs. Return to me with the basket when you've found ten Noblegarden Chocolates.", sourceObjective = "The Noblegarden Vendor wants you to collect 10 Noblegarden Chocolates and return them along with the Egg Basket.", progress = "Do you have the ten Noblegarden Chocolates?", completion = "Well done! And here, please... keep the basket!\n\nRemember, you can always return with more Noblegarden Chocolates to trade for additional items.", sourceObjectiveStatus = "unverified-source-field" }
quests[13503] = { id = 13503, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tisket, a Tasket, a Noblegarden Basket", description = "Here... take this Egg Basket and go hunting for Brightly Colored Eggs. Return to me with the basket when you've found ten Noblegarden Chocolates.", sourceObjective = "The Noblegarden Merchant wants you to collect 10 Noblegarden Chocolates and return them along with the Egg Basket.", progress = "Do you have the ten Noblegarden Chocolates?", completion = "Well done! And here, please... keep the basket!\n\nRemember, you can always return with more Noblegarden Chocolates to trade for additional items.", sourceObjectiveStatus = "unverified-source-field" }
quests[13524] = { id = 13524, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Escape from Silverbrook", description = "You... you're not one of them?  Quick!  Let me out!\n\nWe have to get to Amberpine Lodge immediately!  Once Lieutenant Dumont finds out who these people really are, this town will be reduced to rubble!You will be able to choose one of these rewards:", sourceObjective = "Open the Wooden Cage and help the Freed Alliance Scout escape from Silverbrook. Report to Lieutenant Dumont when you reach Amberpine Lodge.", sourceObjectiveStatus = "unverified-source-field" }
quests[13538] = { id = 13538, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Southern Sabotage", description = "The three towers south of the Wintergrasp river are draining power from the Fortress! \n\nDestroy Shadowsight Tower, Flamewatch Tower or Winter's Edge Tower, then return to me. Remember, only siege vehicles can damage a tower, so make sure to protect them from the Horde!", sourceObjective = "Destroy Shadowsight Tower, Flamewatch Tower or Winter's Edge Tower and return to Tactical Officer Ahbramis in Wintergrasp.", completion = "I heard the explosion from here! Excellent job - we've already begun rerouting the power into the Titan relic to super-charge our own forces.", sourceObjectiveStatus = "unverified-source-field" }
quests[13539] = { id = 13539, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Toppling the Towers", description = "While the Alliance may be pounding on our doors, a true tactician looks beyond the obvious.\n\n\"Attack him where he is unprepared, appear where you are not expected.\"\n\n{name}, I need you to travel across the Wintergrasp River and destroy one of the three towers to the south. Our Warlocks report that the towers are draining power we could use to bolster our own troops.\n\nReturn to me once you've destroyed a tower.", sourceObjective = "Destroy Shadowsight Tower, Flamewatch Tower, or Winter's Edge Tower and return to Tactical Officer Kilrath in Wintergrasp.", progress = "My disgust for Warlocks is only exceeded by my hate for the undead. However, they can both prove useful at times.", completion = "Now in order to kill the enemy, our men must be roused to anger; that there may be advantage from defeating the enemy, they must have their rewards. I hope that these are sufficient for your service to the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[13548] = { id = 13548, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket", sourceObjective = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!", sourceObjectiveStatus = "unverified-source-field" }
quests[13549] = { id = 13549, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tails Up", description = "Along with the Drakkari artifacts, I'm interested in returning to Zandalar with some of the Zul'Drak wildlife. I have males of both the frost leopards and icepaw bears, but I need females!\n\nToo bad that my trapper was killed in a most unfortunate accident. Perhaps you would be willing to fill in for him?\n\nPut the leopards and bears to sleep with this blowgun then lift their tails and return with some females if you would be so kind. They can be found near the Altars of Rhunok, Quetz'lun, and Har'koa.", sourceObjective = "Chronicler To'kini at Zim'Torga wants you to use To'kini's Blowgun on Frost Leopards and Icepaw Bears. Return to him with 3 females of each.", progress = "No, that just won't do. Please return when you have the female leopards and bears that I'll need for the arduous journey back home.", completion = "Very fine specimens indeed, {name}! These are sure to provide many hours of curious speculation amongst my colleagues back home.", sourceObjectiveStatus = "unverified-source-field" }
quests[13556] = { id = 13556, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eggs for Dubra'Jin", description = "How ya doin', mon? Thinkin' ya might be helpin' me out? Bah'Kini be needin' lots o' the raptor eggs to be sacrificin' to Dubra'Jin.\n\nHow ya thinkin' we not be overrun yet by the Drakkari? Dubra'Jin be lendin' us his aid!\n\nWe need ya to gather up the raptor eggs from around the trees outside here in Gundrak. Sometimes the raptors carry 'em to keep 'em warm, too.", sourceObjective = "Ha'wana at Dubra'Jin needs you to collect 12 Gundrak Raptor Eggs.", progress = "Who woulda thought the great Dubra'Jin be wantin' so many eggs? What he gonna do with them anyway?", completion = "One, two, three,... hehe, that be a good number o' them, mon! Now we be safe for quite some time!", sourceObjectiveStatus = "unverified-source-field" }
quests[13559] = { id = 13559, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hodir's Tribute", progress = "No ordinary tributes were good enough for the great Hodir when he walked among the frost giants.\n\nHe might not be with us anymore, but we've kept the tradition of offering tribute to his strength and wisdom.  It would do much for your renown to partake in this tradition, small {class}.", completion = "The Sons of Hodir accept your tribute, small one.  You continue to prove your worth as an ally in more ways than one." }
quests[13571] = { id = 13571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fletcher's Lost and Found", sourceObjective = "Above the stale, unwashed stench, you catch a whiff of a familiar smell!  It appears as if this once-mighty adventurer has a real love for kungaloosh.\n\nPeeking through the bars, you can barely make out the recipe written on his arm....", sourceObjectiveStatus = "unverified-source-field" }
quests[13592] = { id = 13592, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Valiant's Field Training", description = "The tournament is a time for testing your skills against your peers, but we must not forget that the real enemy, the Scourge, will not wait. As you hone your skills against others, so should you maintain your edge in combat against the enemy.\n\nTravel to the area southwest of the Valley of Fallen Heroes and north of Corp'rethar. There, the Scourge raises dead heroes and turns them against us. Defeat these minions of the Scourge, do honor to our allies, and keep yourself prepared for combat.", sourceObjective = "Sir Marcus Barlowe at the Argent Tournament Grounds wants you to kill 10 Converted Heroes.", completion = "Welcome back from your exercises, {name}. Even while we practice for the competition, it's good to remind ourselves that the Scourge is still out there.", sourceObjectiveStatus = "unverified-source-field" }
quests[13593] = { id = 13593, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valiant Of Stormwind", description = "Welcome, champion. Word of your combat prowess has already reached my ears. Do you seek to join Stormwind's tournament delegation?\n\nYou will train and rise through the ranks as you have before, but when you are named a champion of Stormwind, your squire will have the option of carrying our banner into battle.", sourceObjective = "Speak with Marshal Jacob Alerius again if you wish to become a valiant of Stormwind.", completion = "We are proud that you have agreed to train with us and compete on our behalf.", sourceObjectiveStatus = "unverified-source-field" }
quests[13600] = { id = 13600, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Weapon", description = "Of all the times to have such rotten luck!\n\nMy tournament blade has gone missing and I need it for a match this afternoon.\n\nOne of the bards tells me that travelers used to present winter hyacinths to a lonely maiden in return for gifts. Those hyacinths grow only on the ice flowing from the Ironwall Dam, on Crystalsong Forest's northwestern border with Icecrown. Gather the flowers and take them to Drak'Mar lake in northeastern Dragonblight, near its border with Zul'Drak and Grizzly Hills.", sourceObjective = "Bring the Blade of Drak'Mar to Marshal Jacob Alerius at the Argent Tournament Grounds.", progress = "Were the wandering bard's tales true? Have you brought a blade?", completion = "<The marshal accepts the Blade of Drak'Mar from you.>\n\nA fine weapon, and perfectly balanced. It will serve me well in the next match.", sourceObjectiveStatus = "unverified-source-field" }
quests[13603] = { id = 13603, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Blade Fit For A Champion", description = "Good, honest, honed steel may not carry the day. The other combatants are using enchanted blades and I find myself at a disadvantage, but all is not lost.\n\nThere's an old legend from Grizzly Hills about a maiden cursed with a frog's form to protect the blade she has long guarded. She lives among the lake frogs on the shore of Ashwood Lake, just east of Ashwood Post. The only thing said to break the curse is a kiss, freely given. Apply this balm before kissing anything, {name}. Otherwise, you'll catch warts.", sourceObjective = "Retrieve the Ashwood Brand and bring it to Marshal Jacob Alerius at the Argent Tournament Grounds.", progress = "Were you able to recover the blade?", completion = "So the tales were true? This is a fine blade and I have no doubt that it will serve me well in the tournament. You have my thanks, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13604] = { id = 13604, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archivum Data Disc", description = "This platinum disc is surprisingly symmetrical and devoid of any scratches or imperfections.  Engraved along its edge, bold runes spell out the word \"ARCHIVUM.\"\n\nThere must be a device inside Ulduar capable of reading the disc.", sourceObjective = "Bring the Archivum Data Disc to the Archivum Console in Ulduar.", progress = "The console whirrs with energy as the round receptacle opens.", completion = "The platinum disc fits perfectly inside the console.  It begins to spin as its contents are scanned by white beams of light.", sourceObjectiveStatus = "unverified-source-field" }
quests[13606] = { id = 13606, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freya's Sigil", description = "Freya's Sigil is going to be one of the tougher ones, I reckon.\n\nAccording to the Archivum, the essence of the Sigil is tied to her three elder servants, Brightleaf, Ironbranch and Stonebark.  Should any of the elders be harmed, the Sigil's integrity will be compromised.\n\nSparing the elders, however, means that Freya will be more powerful when you face her.\n\nWhat can I say, {name}.  We're stuck between a rock and hard place.", sourceObjective = "Prospector Doren at the Archivum in Ulduar wants you to obtain Freya's Sigil.\n\nFor more information on obtaining Freya's Sigil consult the Archivum Console.", progress = "Freya's sigil, {name}?  Do ye have it?", completion = "Excellent job, {name}.  We're one step closer to saving Azeroth!", sourceObjectiveStatus = "unverified-source-field" }
quests[13607] = { id = 13607, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Celestial Planetarium", description = "Listen, <lad/lass>!  Azeroth's fate is at stake here.\n\nOur only chance is to get to the Celestial Planetarium in time to find this Algalon and stop him from beaming back any messages to his Titan masters.\n\nLocate the Celestial Planetarium and come back with any information you get.  We might still have some time to prepare for Algalon's arrival.", sourceObjective = "Prospector Doren at the Archivum in Ulduar wants you to locate the entrance to the Celestial Planetarium.", progress = "Did you find it, {name}?", completion = "It's locked?  Figures!\n\nLet's see what information this junk heap can give us...", sourceObjectiveStatus = "unverified-source-field" }
quests[13609] = { id = 13609, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hodir's Sigil", description = "Hodir's Sigil won't be easy to obtain.  Not only are ye going to have to defeat Hodir himself, but yer going to have to do it before he destroys the chest that contains it!\n\nCheck the Archivum console if you need more information.  That thing contains more knowledge than all of the world's libraries put together!", sourceObjective = "Prospector Doren at the Archivum in Ulduar wants you to obtain Hodir's Sigil.\n\nFor more information on obtaining Hodir's Sigil, consult the Archivum Console.", progress = "Did ye obtain the sigil, {name}?", completion = "Ye did it!  I don't know how, but ye did!", sourceObjectiveStatus = "unverified-source-field" }
quests[13610] = { id = 13610, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thorim's Sigil", description = "Thorim's not himself, {name}.  He's come under a dark influence.\n\nAn evil presence under the guise of an illusion pretends to be his lost wife, Sif.\n\nYe can't let him be overcome by this impostor's spell.  If he does, the location of his sigil might forever be lost!\n\nYer going to have to beat some sense into him and yer going to have to do it quick.\n\nAs always, the Archivum Console will give ye all the gory details... even the ones ye don't like.", sourceObjective = "Prospector Doren at the Archivum in Ulduar wants you to obtain Thorim's Sigil.\n\nFor more information on obtaining Thorim's Sigil consult the Archivum Console.", progress = "Well, {name}?  Do ye have it?", completion = "Ye never cease to impress, {name}.\n\nYe and me are having a pint together after all this is done, ye hear me?", sourceObjectiveStatus = "unverified-source-field" }
quests[13611] = { id = 13611, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mimiron's Sigil", description = "Mimiron's a clever one.  His entire abode is rigged with some sort of self-destruction mechanism.\n\nUnfortunately yer gonna have to race against it if ye want to get his sigil.  Check the Archivum Console for more details if ye need them.", sourceObjective = "Prospector Doren at the Ulduar Archivum wants you to obtain Mimiron's Sigil.\n\nFor more information on obtaining Mimiron's Sigil consult the Archivum Console.", progress = "Were you able to obtain the sigil, {name}?", completion = "I've got to hand it to you, {name}.  Our odds might not be the best, but I feel a lot better with you lending a hand.", sourceObjectiveStatus = "unverified-source-field" }
quests[13614] = { id = 13614, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Algalon", description = "You really did it, {name}.  Take the sigils to the Archivum Console and see if you can gain access to the Celestial Planetarium.\n\nYou best hurry, <lad/lass>.  Time is of the essence.", sourceObjective = "Bring the Sigils of the Watchers to the Archivum Console in Ulduar.", progress = "The console's bright lights scan the glass surface repeatedly, as if awaiting some form of input.", completion = "Stand by for verification.\n\nAccess to the Celestial Planetarium granted.  Please retrieve your key.", sourceObjectiveStatus = "unverified-source-field" }
quests[13616] = { id = 13616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Edge Of Winter", description = "Curse that death knight for breaking my sword!\n\nIn southern Crystalsong Forest, overlooking the Crystal Vice's exit, you will find Lord Everblaze. Kill him and take the everburning ember from his corpse.\n\nBring it to the center of Winter's Breath Lake in northern Howling Fjord, and use it to free the maiden encased in ice. She is the guardian of an ancient sword and will award it to whoever frees her.\n\nProve your worth and earn the weapon that she has guarded for so long, {name}.", sourceObjective = "Marshal Jacob Alerius at the Argent Tournament Grounds wants you to bring him Winter's Edge.", progress = "Did you win the blade I seek?", completion = "The blade is as fine as the stories say. It would seem there's little reason to complete the repairs on my customary blade. Winter's Edge is far superior and I will continue to carry it. You have my thanks, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13622] = { id = 13622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient History", description = "The pieces fit together to form an elegant hammer.  Its construction appears to be at least partially Titan in nature.\n\nThe console inside the Archivum might have some information regarding this artifact.", sourceObjective = "Bring the Shattered Fragments of Val'anyr to the Archivum Console in the Archivum in Ulduar.", progress = "Awaiting input.", completion = "Analyzing fragments... please stand by.", sourceObjectiveStatus = "unverified-source-field" }
quests[13625] = { id = 13625, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learning The Reins", description = "Most of the tournament's competitions require competitors to master the command of a mount in battle. In order to familiarize you with mounted combat, we've put up training dummies all over the northern part of the tournament grounds.\n\nVisit the stables outside the pavilion, equip your lance, and mount up on the Quel'dorei steed. Familiarize yourself with the tactics available to you and use them to defeat the three different kinds of training dummies.", sourceObjective = "Strike a Melee Target with Thrust 5 times, use Shield-Breaker on 2 vulnerable Ranged Targets, use Charge on 2 vulnerable Charge Targets and then return to Scout Shalyndria at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or the Silver Covenant Pavilion.", progress = "How goes the mounted combat practice?", completion = "Well done, {name}. Mounted combat is often hard to pick up for those accustomed to fighting on foot. I have no doubt that you'll continue to improve with practice, which is more than I can say for some warriors.", sourceObjectiveStatus = "unverified-source-field" }
quests[13627] = { id = 13627, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jack Me Some Lumber", description = "Come closer. No, not too close. Don't want any unnecessary suspicion now, do we?\n\nThis coliseum requires more lumber than we've stockpiled and there's no way I'm going to pay to have it shipped in from Grizzly Hills. At the western end of Crystalsong Forest, by the Great Tree, grow a number of young Crystalsong oaks. They'd provide just the kind of planking we need for building and scaffolding. Take this axe, use it to fell the trees and then hew them into planks, but don't let anyone see you!", sourceObjective = "Bring 12 Rough Hewn Planks to Bezzle Blastbolt at the Argent Tournament Grounds.", progress = "Did you get the \"goods\" we talked about?", completion = "All excellent planks, and the price is right, too! Even better, those Argent Crusade sticks-in-the-mud will never know. They'll get their precious coliseum and I'll get my early completion bonus. Now that's a win-win if I ever saw one.", sourceObjectiveStatus = "unverified-source-field" }
quests[13629] = { id = 13629, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Val'anyr, Hammer of Ancient Kings", description = "The Archivum Console has hinted at a possible way to rebind the fragments of Val'anyr:  you must get the fragments inside the physical form of the being known as Yogg-Saron.\n\nIt sounds like a long shot, but for an artifact of such power you think the risk might just be worth it.", sourceObjective = "Throw the Shattered Pieces of Val'anyr into Yogg-Saron's maw while he's casting Deafening Roar and defeat Yogg-Saron and recover the Reforged Hammer of Ancient Kings.\n\nThis can only be completed in Heroic mode and only if at least one Ulduar Watcher is not assisting you.", progress = "Awaiting input.", completion = "Object integrity confirmed.  Please hold while solidified residue is removed.", sourceObjectiveStatus = "unverified-source-field" }
quests[13631] = { id = 13631, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All Is Well That Ends Well", description = "We'd best hurry now, {name}.  We're going to have to transmit the reply-code from Dalaran.\n\nTake it to Rhonin, I will meet you there.", sourceObjective = "Take the Reply-Code Alpha to Rhonin in Dalaran.", progress = "You're ready, {name}?", completion = "You're here.  Let us hope this works.  For all our sakes.", sourceObjectiveStatus = "unverified-source-field" }
quests[13633] = { id = 13633, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Black Knight of Westfall?", description = "No doubt you've heard the disturbing rumors about the contestant the others are calling the Black Knight. It's said that any rider who was scheduled to face him in combat has met an untimely end.\n\nOf course, we have no definitive proof of anything, but it wouldn't hurt to look into this knight's background.\n\nHe claims to be descended from the Cooper family of Westfall. Would you visit their residence in the western part of Moonbrook in Westfall? See if you can find any proof of his story.", sourceObjective = "Investigate the Black Knight's claims and return to Crusader Rhydalla at the Argent Tournament Grounds with your findings.", progress = "Have you found anything related to the Black Knight's story?", completion = "So you're saying this knight's story is a sham? Most suspicious. Dishonorable at the least, and murderous at the worst. Still, we can't confront him until we know for certain whether he was involved in these murders.\n\nDo nothing to arouse his suspicions, {name}. Discretion will serve us well as we continue to investigate.", sourceObjectiveStatus = "unverified-source-field" }
quests[13634] = { id = 13634, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Black Knight of Silverpine?", description = "No doubt you've heard the disturbing rumors about the contestant the others are calling the Black Knight. It's said that any rider who was scheduled to face him in combat has met an untimely end.\n\nOf course, we have no definitive proof of anything, but it wouldn't hurt to look into this knight's background.\n\nHe claims to hail from Valgan's Field in Silverpine Forest. It's a small farm on the western shore of Lordamere Lake. Would you visit the farm and let me know if there's any truth to his story?", sourceObjective = "Investigate the Black Knight's claims and return to Crusader Rhydalla at the Argent Tournament Grounds with your findings.", progress = "Have you found anything related to the Black Knight's story?", completion = "So you're saying this knight's story is a sham? Most suspicious. Dishonorable at the least, and murderous at the worst. Still, we can't confront him until we know for certain whether he was involved in these murders.\n\nDo nothing to arouse his suspicions, {name}. Discretion will serve us well as we continue to investigate.", sourceObjectiveStatus = "unverified-source-field" }
quests[13641] = { id = 13641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Seer's Crystal", description = "Now that we know there's no truth to the Black Knight's stories, we must find a way to connect him to the murdered knights.\n\nI know a way to reveal the truth about how they died, but it requires a rare material. We must gain a seer's crystal, found only among the unbound seers who congregate near night elf ruins in the Forlorn Woods in the central part of Crystalsong Forest. Find one of these seers, {name}, and bring me the crystal it holds.", sourceObjective = "Bring a Seer's Crystal to Crusader Rhydalla at the Argent Tournament Grounds.", progress = "Have you located a seer's crystal?", completion = "This one will do nicely. All that remains is to imbue it with the power of the Light, giving it the ability to find truth amid deception.", sourceObjectiveStatus = "unverified-source-field" }
quests[13643] = { id = 13643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Stories Dead Men Tell", description = "The crystal will reveal the truth about how three of the tournament's combatants died. Take it with you to the graveyard east of the Tournament Grounds and use it before the graves of Sir Wendell Balfour, Lorien Sunblaze, and Conall Irongrip.\n\nIf indeed these men were murdered, then we must find a way to tie it to the Black Knight before he strikes again. Look closely at what the crystal tells you, {name}, for we must be certain these deaths were not accidental.", sourceObjective = "Use the Seer's Crystal at the graves of Sir Wendell Balfour, Lorien Sunblaze, and Conall Irongrip to determine how they died, then return to Crusader Rhydalla.", progress = "Have you visisted the graves of the slain combatants?", completion = "So you say Lorien Sunblaze was done in by poison and Sir Wendell was burnt alive? Dreadful ways to die, both of them. Only Conall was killed by cold steel, and from your description, it was a coward's strike, not honorable combat that laid him in his grave.\n\nAll three sparred with and were scheduled to fight the Black Knight. This cannot be a coincidence. Now, we must find a way to prove it was the Black Knight's work.", sourceObjectiveStatus = "unverified-source-field" }
quests[13649] = { id = 13649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Justin's Fun Test", description = "Hey there!  You look like you can handle your brew.  But can you handle your brew mug? \n\nThe Dark Irons have come back with a vengeance to ruin our celebration.  Tossing mugs at them is the best way to stop them, but first, let's see if you can toss one at old S.T.O.U.T. here.\n\nIt's easy, pick up a complimentary sampler and take a drink.  Just make sure you're facing S.T.O.U.T.  Talk to me after you've hit him 5 times.", sourceObjective = "Use the Complimentary Brewfest Sampler to hit S.T.O.U.T. 5 times, then talk to Boxey Boltspinner.", sourceObjectiveStatus = "unverified-source-field" }
quests[13654] = { id = 13654, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "There's Something About the Squire", description = "Every day, the Black Knight's squire, Maloric, makes a big show of heading to Crystalsong Forest with his axe over his shoulder. He wants us to believe he's chopping wood, but he never returns with more than a few twigs.\n\nHe usually goes toward the ruins southwest of the Mirror of Twilight. He spends a lot of time out there, even for a squire with responsibilities to his knight.\n\nFind a way to distract or incapacitate him and search him. If he's up to something, we'll know it.", sourceObjective = "Obtain a Large Femur from a Skeletal Woodcutter and use it to incapacitate Maloric. Search Maloric for evidence, then report back to Crusader Rhydalla at the Argent Tournament Grounds.", progress = "Did the squire's behavior yield any clues?", completion = "<Crusader Rhydalla examines the bag's contents with a look of disgust on her face.>\n\nIt's all here, {name}: the poison that killed Lorien, a collection of knives, torches, and oil. No man has cause to possess these things here and no squire would do so without orders from his knightly master. We've found our murderer, {name}, but who is he working for?", sourceObjectiveStatus = "unverified-source-field" }
quests[13662] = { id = 13662, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gaining Acceptance", progress = "You've worked your way up through the Brotherhood's corporate hierarchy, {race}. We have begun to look favorably upon you. Quite an accomplishment!\n\nIf you're interested in more work and earning more respect amongst us, listen up.\n\nWe can refine the fiery flux by adding a simple Dark Iron residue to the mix. The Dark Iron residue can be found in Blackrock Depths.\n\nBring me all the Dark Iron residue you find!", completion = "Keep the residue pouring in!" }
quests[13663] = { id = 13663, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Black Knight's Orders", description = "We must discover who sent the Black Knight to the tournament and what his master hopes to gain by killing the competitors.\n\nThe Kirin Tor has offered to help in this matter and provided us with something to help our search.\n\nTake this enchanted bridle to the Black Knight's camp on the eastern edge of the tournament grounds and use it to gain control over the Black Knight's gryphon. The bridle's magic will force the gryphon to take you to his master's home. Search it and return with anything you find.", sourceObjective = "Use the Enchanted Bridle to gain control of the Black Knight's Gryphon and ride it to its destination. Once you have arrived, recover the Stolen Tournament Invitation and the Black Knight's Orders and bring them to Crusader Rhydalla at the Argent Tournament Grounds.", progress = "What did you discover?", completion = "<Crusader Rhydalla's face pales as she reads the orders.>\n\nThis can only mean one thing, {name}. The Black Knight is a member of the Cult of the Damned and has been sent by Arthas to disrupt the tournament!\n\nThe Black Knight has proven himself a fearsome combatant, and you will need to be every bit as good if you wish to face him. When you are a champion, return to me and we'll find a way to ensure his defeat.", sourceObjectiveStatus = "unverified-source-field" }
quests[13664] = { id = 13664, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Black Knight's Fall", description = "We must put an end to the Black Knight's scheming, and show those who oppose us that we will not stand by and allow our champions to be murdered.\n\nBy now, he will suspect that someone is on his trail. Challenge him in the light of day, where he cannot refuse or murder in the dark, {name}.\n\nUse my argent charger for the battle. It's housed in the stables.\n\nSpeak to Squire Cavin at the Ring of Champions. The squire will call the Black Knight to battle, but you will make him answer for his crimes.", sourceObjective = "Defeat the Black Knight and then speak to Crusader Rhydalla at the Argent Tournament Grounds.", progress = "Is it done?", completion = "With the death of the Black Knight, the tournament may once again serve its purpose. The champions of the Horde and Alliance may demonstrate their skill at arms and train for the day when Arthas and his minions will no longer threaten us.\n\nYou have the thanks of the Argent Crusade, {name}, and that of all who have answered our call.", sourceObjectiveStatus = "unverified-source-field" }
quests[13665] = { id = 13665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grand Melee", description = "The grand melee is the most important of the tournament's competitions. The people of Stormwind adore their knights and are looking forward to seeing us win the melee. To that end, they've been honing their skills against the other valiants.\n\nI suggest you do the same.\n\nGo to the stables outside the pavilion, equip your lance, mount the stabled Elwynn steed, and challenge the valiants. They wait in the Alliance Valiants' Ring just outside our tent.", sourceObjective = "Bring 3 Marks of the Valiant to Captain Joseph Holley at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion.", progress = "Have you completed your training for the grand melee?", completion = "Well done. Training against the other valiants is one of the best ways to prepare yourself for tournament competition. I know you'll make Stormwind proud, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13666] = { id = 13666, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Blade Fit For A Champion", description = "Some of the champions believe an ancient weapon born of Northrend will bring them luck in the tourney. I have agreed to help them search for these weapons.\n\nThere's an old legend from Grizzly Hills about a maiden cursed with a frog's form to protect the blade she has long guarded. She lives among the lake frogs on the shore of Ashwood Lake, just east of Ashwood Post. The only thing said to break the curse is a kiss, freely given. Apply this balm before kissing anything, {name}. Otherwise, you'll catch warts.", sourceObjective = "Retrieve the Ashwood Brand and bring it to Arcanist Taelis at the Argent Tournament Grounds.", progress = "Were you able to recover the blade?", completion = "So there is some truth to those old tales? It seems they did not lie about the quality of the blade. Well done, {name}. The champion who wields it will be a lucky man, indeed.", sourceObjectiveStatus = "unverified-source-field" }
quests[13667] = { id = 13667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Argent Tournament", description = "We have invited you here to test your skill and valor against others who have bravely opposed the Scourge. Many have been our divisions, but the time has come for heroes fighting under all banners to test their blades against one another in preparation for facing our mutual enemy.\n\nArcanist Taelis is the Silver Covenant's representative to the tournament and he'll enter your name into the rolls and begin your training. Seek him out inside the large Alliance tent in the northeastern part of the grounds.", sourceObjective = "Speak with Arcanist Taelis at the Argent Tournament grounds to enroll in the tournament.", completion = "I have entered your name in the rolls, {name}. As an aspirant you will train with others who wish to compete in the tournament and hone your mounted combat skills. Once you have proven yourself, you will be allowed to enter the lowest rank of competition on behalf of your capital city.", sourceObjectiveStatus = "unverified-source-field" }
quests[13668] = { id = 13668, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Argent Tournament", description = "We have invited you here to test your skill and valor against others who have bravely opposed the Scourge. Many have been our divisions, but the time has come for heroes fighting under all banners to test their blades against one another in preparation for facing our mutual enemy.\n\nMagister Edien Sunhollow is the Sunreaver representative to the tournament and he'll enter your name into the rolls and begin your training. Seek him out inside the large Horde tent in the southeastern part of the grounds.", sourceObjective = "Speak with Magister Edien Sunhollow at the Argent Tournament grounds to enroll in the tournament.", completion = "I have entered your name in the rolls, {name}. As an aspirant you will train with others who wish to compete in the tournament and hone your mounted combat skills. Once you have proven yourself, you will be allowed to enter the lowest rank of competition on behalf of your capital city.", sourceObjectiveStatus = "unverified-source-field" }
quests[13669] = { id = 13669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Weapon", description = "Our champions have taken a liking to ancient weapons produced here in Northrend.\n\nI've heard the bards telling tales of travelers offering winter hyacinths to a lonely maiden in return for gifts. Those hyacinths grow only on the ice flowing from the Ironwall Dam, on Crystalsong Forest's northwestern border with Icecrown. Gather the flowers and take them to the circle of lamps in Drak'Mar Lake in northeastern Dragonblight, near Zul'Drak and Grizzly Hills. Ask the lonely maiden for a worthy blade.", sourceObjective = "Bring the Blade of Drak'Mar to Arcanist Taelis at the Argent Tournament Grounds.", progress = "Were the wandering bard's tales true? Have you brought a blade?", completion = "There's no doubt that this is a blade of exquisite quality and balance. Now I understand why these weapons are so coveted among the champions of the Alliance.", sourceObjectiveStatus = "unverified-source-field" }
quests[13670] = { id = 13670, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Edge Of Winter", description = "The Ironforge grand champion's squire told me an intriguing story.\n\nIn southern Crystalsong Forest, overlooking the Crystal Vice's exit, you will find Lord Everblaze. Kill him and take the everburning ember from his corpse.\n\nBring it to the center of Winter's Breath Lake in northern Howling Fjord, and use it to free the maiden encased in ice. She is the guardian of an ancient sword and will award it to whoever frees her.\n\nProve your worth and earn the weapon that she has guarded for so long, {name}.", sourceObjective = "Arcanist Taelis at the Argent Tournament Grounds wants you to bring him Winter's Edge.", progress = "Did you win the blade?", completion = "The blade is as fine as the squire said it would be, but where did he find out about it? No matter; it will serve its new owner well. Perhaps it's only fair that Ironforge's grand champion be the one to wield it.", sourceObjectiveStatus = "unverified-source-field" }
quests[13671] = { id = 13671, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Training In The Field", description = "The tournament is a time for testing your skills against your peers, but we must not forget that the real enemy, the Scourge, will not wait. As you learn to master mounted combat, do not forget to practice the skills that have served you well all these years. Show us that you can face the Scourge with honor and bravery, and you will earn your right to compete in this tournament.\n\nTravel to Icecrown and slay any Scourge you see there, but stay clear of the Bombardment, where you would be overwhelmed.", sourceObjective = "Avareth Swiftstrike at the Argent Tournament Grounds wants you to kill 8 Icecrown Scourge. You may kill Scourge in any part of Icecrown except the Bombardment.", progress = "Have you tested yourself in combat against the Scourge?", completion = "You have shown yourself a capable combatant, {name} and you will serve as an example to the rest of the aspirants who clamor to compete on behalf of the Alliance.", sourceObjectiveStatus = "unverified-source-field" }
quests[13672] = { id = 13672, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Up To The Challenge", description = "When you have mastered the skills of the aspirant, you may choose to take the aspirant's challenge. The challenge will test your mounted combat skills and assess whether or not you're prepared to become a valiant. Should you pass, you will be able to join your capital city's delegation as a valiant.\n\nWhen you are ready to begin the challenge, return to me.", sourceObjective = "Present Arcanist Taelis at the Argent Tournament with 15 Aspirant's Seals to signify you're ready to undergo the aspirant's challenge.", progress = "Do you wish to take the aspirant's challenge?", completion = "Very well, I will make the arrangements.", sourceObjectiveStatus = "unverified-source-field" }
quests[13673] = { id = 13673, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Blade Fit For A Champion", description = "Some of the champions believe an ancient weapon born of Northrend will bring them luck in the tourney. I have agreed to help them search for these weapons.\n\nThere's an old legend from Grizzly Hills about a maiden cursed with a frog's form to protect the blade she has long guarded. She lives among the lake frogs on the shore of Ashwood Lake, just east of Ashwood Post. The only thing said to break the curse is a kiss, freely given. Apply this balm before kissing anything, {name}. Otherwise, you'll catch warts.", sourceObjective = "Retrieve the Ashwood Brand and bring it to Magister Edien Sunhollow at the Argent Tournament Grounds.", progress = "Were you able to recover the blade?", completion = "So there is some truth to those old tales? It seems they did not lie about the quality of the blade. Well done, {name}. The champion who wields it will be a lucky man, indeed.", sourceObjectiveStatus = "unverified-source-field" }
quests[13674] = { id = 13674, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Weapon", description = "Our champions have taken a liking to ancient weapons produced here in Northrend.\n\nI've heard the bards telling tales of travelers offering winter hyacinths to a lonely maiden in return for gifts. Those hyacinths grow only on the ice flowing from the Ironwall Dam, on Crystalsong Forest's northwestern border with Icecrown. Gather the flowers and take them to the circle of lamps in Drak'Mar Lake in northeastern Dragonblight, near Zul'Drak and Grizzly Hills. Ask the lonely maiden for a worthy blade.", sourceObjective = "Bring the Blade of Drak'Mar to Magister Edien Sunhollow at the Argent Tournament Grounds.", progress = "Were the wandering bard's tales true? Have you brought a blade?", completion = "There's no doubt that this is a blade of exquisite quality and balance. Now I understand why these weapons are so coveted among the champions of the Alliance.", sourceObjectiveStatus = "unverified-source-field" }
quests[13675] = { id = 13675, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Edge Of Winter", description = "I heard an interesting story from one of the Ogrimmar valiants.\n\nIn southern Crystalsong Forest, overlooking the Crystal Vice's exit, you will find Lord Everblaze. Kill him and take the everburning ember from his corpse.\n\nBring it to the center of Winter's Breath Lake in northern Howling Fjord, and use it to free the maiden encased in ice. She is the guardian of an ancient sword and will award it to whoever frees her.\n\nProve your worth and earn the weapon that she has guarded for so long, {name}.", sourceObjective = "Magister Edien Sunhollow at the Argent Tournament Grounds wants you to bring him Winter's Edge.", progress = "Did you win the blade?", completion = "The blade is as fine as the valiant said it would be, but where did he find out about it? No matter; it will serve its new owner well. Perhaps it's only fair that Orgrimmar's grand champion be the one to wield it.", sourceObjectiveStatus = "unverified-source-field" }
quests[13676] = { id = 13676, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Training In The Field", description = "The tournament is a time for testing your skills against your peers, but we must not forget that the real enemy, the Scourge, will not wait. As you learn to master mounted combat, do not forget to practice the skills that have served you well all these years. Show us that you can face the Scourge with honor and bravery, and you will earn your right to compete in this tournament.\n\nTravel to Icecrown and slay any Scourge you see there, but stay clear of the Bombardment, where you would be overwhelmed.", sourceObjective = "Amariel Sunsworn at the Argent Tournament Grounds wants you to kill 8 Icecrown Scourge. You may kill Scourge in any part of Icecrown except the Bombardment.", progress = "Have you tested yourself in combat against the Scourge?", completion = "You have shown yourself a capable combatant, {name} and you will serve as an example to the rest of the aspirants who clamor to compete on behalf of the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[13677] = { id = 13677, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learning The Reins", description = "Most of the tournament's competitions require competitors to master the command of a mount in battle. In order to familiarize you with mounted combat, we've put up training dummies all over the northern part of the tournament grounds.\n\nVisit the stables outside the pavilion, equip your lance, and mount up on the Sunreaver hawkstrider. Familiarize yourself with the mount and use its abilities to defeat the three different kinds of training dummies.", sourceObjective = "Strike a Melee Target with Thrust 5 times, use Shield-Breaker on 2 vulnerable Ranged Targets, use Charge on 2 vulnerable Charge Targets, and then return to Galathia Brightdawn at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or the Sunreaver Pavilion.", progress = "How goes the mounted combat practice?", completion = "Well done, {name}. Mounted combat is often hard to pick up for those accustomed to fighting on foot. I have no doubt that you'll continue to improve with practice, which is more than I can say for some warriors.", sourceObjectiveStatus = "unverified-source-field" }
quests[13678] = { id = 13678, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Up To The Challenge", description = "When you have mastered the skills of the aspirant, you may choose to take the aspirant's challenge. The challenge will test your mounted combat skills and assess whether or not you're prepared to become a valiant. Should you pass, you will be able to join your capital city's delegation as a valiant.\n\nWhen you are ready to begin the challenge, return to me.", sourceObjective = "Present Magister Edien Sunhollow at the Argent Tournament with 15 Aspirant's Seals to signify you're ready to undergo the aspirant's challenge.", progress = "Do you wish to take the aspirant's challenge?", completion = "Very well, I will make the arrangements.", sourceObjectiveStatus = "unverified-source-field" }
quests[13679] = { id = 13679, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Aspirant's Challenge", description = "You have trained hard as an aspirant, {name}, and now the time has come to test your mounted combat skills against a skilled opponent.\n\nEquip your lance, then go to the stables outside the pavilion and mount up on the stabled Quel'dorei steed.\n\nAt the Aspirants' Ring on the northern side of the tournament grounds, you'll find Squire David. He'll make certain that you're ready for the fight and call out your opponent.\n\nGood luck, {name}. May your horse be steady and your aim true.", sourceObjective = "Speak with Squire David to summon your opponent. Once you have defeated the Argent Valiant, return to Arcanist Taelis at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion.", progress = "Have you faced your challenge?", completion = "Congratulations are in order, {name}. You have bested your challenger and earned the right to advance to the rank of valiant.", sourceObjectiveStatus = "unverified-source-field" }
quests[13680] = { id = 13680, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Aspirant's Challenge", description = "You have trained hard as an aspirant, {name}, and now the time has come to test your mounted combat skills against an experienced opponent.\n\nEquip your lance, then go to the stables outside the pavilion and mount the Sunreaver hawkstrider.\n\nAt the Aspirants' Ring on the northern side of the tournament grounds, you'll find a human child called Squire David. He'll ask if you're ready for the fight and call out your opponent.\n\nGood luck, {name}. May your mount be steady and your aim true.", sourceObjective = "Speak with Squire David to summon your opponent. Once you have defeated the Argent Valiant, return to Magister Edien Sunhollow at the Argent Tournament Grounds.", progress = "Have you faced your challenge?", completion = "Congratulations are in order, {name}. You have bested your challenger and earned the right to advance to the rank of valiant.", sourceObjectiveStatus = "unverified-source-field" }
quests[13681] = { id = 13681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Chip Off the Ulduar Block", description = "Getting stone for this job has been a nightmare, I tell ya! There are tons of stone available from ruins in safe places, but those holier-than-thou paladins won't go for it. Something about 'priceless artifacts.'\n\nAnyway, whining about that isn't going to get this place built. There are tons of crumbling titan ruins in the Foot Steppes and at the Inventor's Library in Storm Peaks. Take my, uh, 'chisel' with you and see if you can break those huge blocks into useful pieces.", sourceObjective = "Bring 15 Small Stone Blocks to Bozzle Blastbolt at the Argent Tournament Grounds.", progress = "Did you get that stone?", completion = "These should do. Just don't go around blabbing to those crusaders about where you got them from. I'm sure they'll get upset. But, hey, it's not like the titans have come back for them. They're fair game, I say. Good work, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13682] = { id = 13682, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Threat From Above", description = "Highlord Tirion Fordring has doubled the guard since your exposure of the Cult of the Damned's infiltrator. He doesn't believe that they will stop just because their Black Knight has been defeated.\n\nOur skytalon scouts have reported sighting a frost wyrm named Chillmaw leading a cult raiding party. If we don't intercept them, the tournament will come under attack. The scouts reporting seeing Chillmaw to the southwest, flying over the area between the Ironwall Rampart and Aldur'thar.", sourceObjective = "Eadric the Pure at the Argent Tournament wants you to defeat Chillmaw and 3 Cultist Bombardiers.", completion = "{name}, you and your allies have spared the tournament from a devastating attack. Though our skytalon riders are brave, they  have their hands full keeping the peace on the tournament grounds and would be hard-pressed to defend the skies against the cult's attack. You have the thanks of the Argent Crusade and all who have gathered here to compete.", sourceObjectiveStatus = "unverified-source-field" }
quests[13684] = { id = 13684, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Valiant Of Stormwind", description = "You've proven yourself worthy of competing under the banner of Stormwind, {name}. Now, you should introduce yourself to Marshal Jacob Alerius, who leads the Stormwind delegation. As Stormwind's grand champion, he will enter you into the tournament on behalf of the city and oversee your training and testing as valiant.\n\nIt has been an honor working with you, {name}, and I wish you luck in the competition ahead.", sourceObjective = "Speak with Marshal Jacob Alerius at the Argent Tournament Grounds  to become a valiant of Stormwind.", completion = "Welcome aboard then, Valiant {name}. The Stormwind delegation is proud to count you among its members.", sourceObjectiveStatus = "unverified-source-field" }
quests[13685] = { id = 13685, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Valiant Of Ironforge", description = "You've proven yourself worthy of competing under the banner of Ironforge, {name}. Now, you should introduce yourself to Lana Stouthammer, who leads the Ironforge delegation. As Ironforge's grand champion, she will enter you into the tournament on behalf of the city and oversee your training and testing as valiant.\n\nIt has been an honor working with you, {name}, and I wish you luck in the competition ahead.", sourceObjective = "Speak with Lana Stouthammer at the Argent Tournament Grounds  to become a valiant of Ironforge.", completion = "It's good to meet you, valiant. Ironforge needs competitors like you to prevail in the tournament.", sourceObjectiveStatus = "unverified-source-field" }
quests[13688] = { id = 13688, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Valiant Of Gnomeregan", description = "You've proven yourself worthy of competing under the banner of Gnomeregan, {name}. Now, you should introduce yourself to Ambrose Boltspark, who leads the Gnomeregan delegation. As the gnomish grand champion, he will enter you into the tournament on behalf of the city and oversee your training and testing as valiant.\n\nIt has been an honor working with you, {name}, and I wish you luck in the competition ahead.", sourceObjective = "Speak with Ambrose Boltspark at the Argent Tournament Grounds  to become a valiant of Gnomeregan.", completion = "Welcome aboard then, Valiant {name}. The Gnomeregan delegation is proud to count you among its members.", sourceObjectiveStatus = "unverified-source-field" }
quests[13689] = { id = 13689, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Valiant Of Darnassus", description = "You've proven yourself worthy of competing under the banner of Darnassus, {name}. Now, you should introduce yourself to Jaelyne Evensong, who leads the Darnassus delegation. As the night elf grand champion, she will enter you into the tournament on behalf of the city and oversee your training and testing as valiant.\n\nIt has been an honor working with you, {name}, and I wish you luck in the competition ahead.", sourceObjective = "Speak with Jaelyne Evensong at the Argent Tournament Grounds  to become a valiant of Darnassus.", completion = "Welcome to the Darnassus tournament delegation, {name}. It will be a pleasure to train and compete alongside you.", sourceObjectiveStatus = "unverified-source-field" }
quests[13690] = { id = 13690, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Valiant Of The Exodar", description = "You've proven yourself worthy of competing under the banner of the Exodar, {name}. Now, you should introduce yourself to Colosos, who leads the Exodar delegation. As the draenei grand champion, he will enter you into the tournament on behalf of the city and oversee your training and testing as valiant.\n\nIt has been an honor working with you, {name}, and I wish you luck in the competition ahead.", sourceObjective = "Speak with Colosos at the Argent Tournament Grounds  to become a valiant of the Exodar.", completion = "Welcome aboard then, Valiant {name}. The Exodar's delegation is proud to count you among its members.", sourceObjectiveStatus = "unverified-source-field" }
quests[13691] = { id = 13691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Valiant Of Orgrimmar", description = "You've proven yourself worthy of competing under the banner of Orgrimmar, {name}. Now, you should speak with Mokra the Skullcrusher, who leads Orgrimmar's competitors. As Orgrimmar's grand champion, he will enter you into the tournament on behalf of the city and oversee your training and testing as valiant.\n\nIt has been an honor working with you, {name}, and I wish you luck in the competition ahead.", sourceObjective = "Speak with Mokra the Skullcrusher at the Argent Tournament Grounds  to become a valiant of Orgrimmar.", completion = "So you want to compete for Orgrimmar? Just because you've beaten up a few dummies doesn't mean you'll win, but you'll be training with the best from now on.", sourceObjectiveStatus = "unverified-source-field" }
quests[13692] = { id = 13692, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sword and the Sea", description = "My sword was lost at sea.  Catch it and bring it back!", sourceObjective = "Old Man Barlo in Crystalsong Forest wants you to bring him the Sword of Knighthood.", sourceObjectiveStatus = "unverified-source-field" }
quests[13693] = { id = 13693, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Valiant Of Sen'jin", description = "You've proven yourself worthy of competing under the banner of Sen'jin, {name}. Now, you should speak with Zul'tore who leads Sen'jin's warriors. As the troll grand champion, he will enter you into the tournament on behalf of the city and oversee your training and testing as valiant.\n\nIt has been an honor working with you, {name}, and I wish you luck in the competition ahead.", sourceObjective = "Speak with Zul'tore at the Argent Tournament Grounds  to become a valiant of Sen'jin.", completion = "You think you have what it takes to compete for Sen'jin? I think we'll be finding out.", sourceObjectiveStatus = "unverified-source-field" }
quests[13694] = { id = 13694, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Valiant Of Thunder Bluff", description = "You've proven yourself worthy of competing under the banner of Thunder Bluff, {name}. Now, you should speak with Runok Wildmane, who leads Thunder Bluff's competitors. As Thunder Bluff's grand champion, he will enter you into the tournament on behalf of the city and oversee your training and testing as valiant.\n\nIt has been an honor working with you, {name}, and I wish you luck in the competition ahead.", sourceObjective = "Speak with Runok Wildmane at the Argent Tournament Grounds  to become a valiant of Thunder Bluff.", completion = "On behalf of Thunder Bluff and its warriors, I welcome you, {name}. Always fight honorably and bravely beneath our banner.", sourceObjectiveStatus = "unverified-source-field" }
quests[13695] = { id = 13695, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Valiant Of Undercity", description = "You've proven yourself worthy of competing under the banner of the Undercity, {name}. Now, you should speak with Deathstalker Visceri, who leads the Undercity delegation. As grand champion, he will enter you into the tournament on behalf of the city and oversee your training and testing as valiant.\n\nIt has been an honor working with you, {name}, and I wish you luck in the competition ahead.", sourceObjective = "Speak with Deathstalker Visceri at the Argent Tournament Grounds  to become a valiant of the Undercity.", completion = "Welcome to the Undercity delegation. {name}. As a valiant, you'll train with us to prepare you for the highest level of competition.", sourceObjectiveStatus = "unverified-source-field" }
quests[13696] = { id = 13696, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Valiant Of Silvermoon", description = "You've proven yourself worthy of competing under the banner of Silvermoon, {name}. Now, you should speak with Eressea Dawnsinger, who leads the Silvermoon delegation. As Silvermoon's grand champion, she will enter you into the tournament on behalf of the city and oversee your training and testing as valiant.\n\nIt has been an honor working with you, {name}, and I wish you luck in the competition ahead.", sourceObjective = "Speak with Eressea Dawnsinger at the Argent Tournament Grounds  to become a valiant of Silvermoon.", completion = "So you want to compete for Silvermoon? Very well. I'll add you to the rolls and you may begin working with the other valiants immediately.", sourceObjectiveStatus = "unverified-source-field" }
quests[13697] = { id = 13697, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Valiant's Charge", description = "In your training as a valiant, you'll have the chance to test your skills against valiants representing other cities. Although a valiant's battles are not a formal part of the competition, you will learn valuable lessons about the fighting styles and weaknesses of your opponents.\n\nThe valiants are a spirited lot, competing amongst themselves for honor and notoriety.\n\nTrain as a valiant until you are confident of your ability to best all who face you, then bring me the seals you have earned.", sourceObjective = "Bring 25 Valiant's Seals to Mokra the Skullcrusher at the Argent Tournament Grounds.", progress = "Are you ready to demonstrate your mastery of the valiant's skills?", completion = "Impressive, valiant. I will make the arrangements for your test immediately.", sourceObjectiveStatus = "unverified-source-field" }
quests[13699] = { id = 13699, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Valiant's Challenge", description = "You are nearly ready to compete on behalf of Stormwind in the grand melee. To prove yourself worthy to enter the lists on behalf of our city, you must defeat a champion of the Argent Crusade.\n\nGo to the stables outside the pavilion, equip your lance, and mount up. Speak to Squire Danny at the Argent Valiants' Ring on the western edge of the grounds. The squire will call out your opponent when you're ready.\n\nAfter the battle is concluded, we will speak of the outcome.", sourceObjective = "Speak with Squire Danny to summon your opponent. Once you have defeated the Argent Champion, return to Marshal Jacob Alerius at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion.", progress = "Have you overcome the Argent champion?", completion = "You have proven yourself worthy of the title of champion, {name}. You will compete at the tournament's highest level on behalf of Stormwind, riding in the grand melee with your weapon at the ready and our mighty pennant at your back.", sourceObjectiveStatus = "unverified-source-field" }
quests[13702] = { id = 13702, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Champion Rises", description = "Congratulations, {name}. You have mastered many kinds of combat and overcome all the challenges you've faced. There can be no doubt that you are ready to compete with the best warriors who have gathered at the tournament, against the champions of the capital cities.\n\nJusticar Mariel Trueheart has asked to speak with you, {name}, and to formally enter you in the champions' grand melee.", sourceObjective = "Speak with Justicar Mariel Trueheart at the Argent Tournament Grounds.", completion = "I welcome you as a champion of the tournament, {name}. As a champion, you will be able to compete for the grand championship of the tournament. You may also choose to become a valiant with another Alliance city's delegation and in time, a champion for that city as well.\n\nAll champions must have the assistance of a squire, {name}, and you are no exception. Allow me to appoint one of ours to accompany you in battle. He will proudly carry the banner of any city that has named you a champion.", sourceObjectiveStatus = "unverified-source-field" }
quests[13703] = { id = 13703, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valiant Of Ironforge", description = "Welcome, champion. Word of your combat prowess has already reached my ears. Do you seek to join Ironforge's tournament delegation?\n\nYou will train and rise through the ranks as you have before, but when you are named a champion of Ironforge, your squire will have the option of carrying our banner into battle.", sourceObjective = "Speak with Lana Stouthammer again if you wish to become a valiant of Ironforge.", completion = "We are proud that you have decided to join us and I know you will shine on the field.", sourceObjectiveStatus = "unverified-source-field" }
quests[13704] = { id = 13704, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valiant Of Gnomeregan", description = "Welcome, champion. Word of your combat prowess has already reached my ears. Gnomeregan's delegation could really benefit from a {class} like you.\n\nYou will train and rise through the ranks as you have before, but when you are named a champion of Gnomeregan, your squire will have the option of carrying our banner into battle.", sourceObjective = "Speak with Ambrose Boltspark again if you wish to become a valiant of Gnomeregan.", completion = "We're proud to count you among us, {name}, and we look forward to training with you.", sourceObjectiveStatus = "unverified-source-field" }
quests[13705] = { id = 13705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valiant Of The Exodar", description = "Welcome, champion. Word of your deeds has already reached my ears. Do you wish to join the Exodar's tournament delegation?\n\nYou will train and rise through the ranks as you have before, but when you are named a champion of the Exodar, your squire will have the option of carrying our banner into battle.", sourceObjective = "Speak with Colosos again if you wish to become a valiant of the Exodar.", completion = "It's good to have you on our team, {name}. We will all benefit from training with you.", sourceObjectiveStatus = "unverified-source-field" }
quests[13706] = { id = 13706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valiant Of Darnassus", description = "Welcome, champion. I have heard of your accomplishments and we would be honored if you would join the delegation from Darnassus.\n\nYou will train and rise through the ranks as you have before, but when you are named a champion of Darnassus, your squire will have the option of carrying our banner into battle.", sourceObjective = "Speak with Jaelyne Eveonsong again if you wish to become a valiant of Darnassus.", completion = "The warriors of Darnassus are honored to fight and train beside you.", sourceObjectiveStatus = "unverified-source-field" }
quests[13707] = { id = 13707, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valiant Of Orgrimmar", description = "So, you have become a champion? Then, you have proven yourself a worthy combatant and I would proudly welcome you into Orgrimmar's delegation.\n\nYou will train and rise through the ranks as you have before, but when you are named a champion of Orgrimmar, your gruntling will have the option of carrying our banner into battle.", sourceObjective = "Speak with Mokra the Skullcrusher again if you wish to become a valiant of Orgrimmar.", completion = "Welcome, then, {name}. I look forward to watching you train with my men.", sourceObjectiveStatus = "unverified-source-field" }
quests[13708] = { id = 13708, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valiant Of Sen'jin", description = "Greetings, champion. If you are willing, I would welcome you into Sen'jin's tournament delegation.\n\nYou will train and rise through the ranks as you have before, but when you are named a champion of Sen'jin, your gruntling will have the option of carrying our banner into battle.", sourceObjective = "Speak with Zul'tore again if you wish to become a valiant of Sen'jin.", completion = "I am glad that you have decided to join us and look forward to seeing you in action.", sourceObjectiveStatus = "unverified-source-field" }
quests[13709] = { id = 13709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valiant Of Thunder Bluff", description = "Welcome, champion. As grand champion of the Thunder Bluff delegation, I would be honored to welcome you into our ranks, if you are willing.\n\nYou will train and rise through the ranks as you have before, but when you are named a champion of Thunder Bluff, your gruntling will have the option of carrying our banner into battle.", sourceObjective = "Speak with Runok Wildmane again if you wish to become a valiant of Thunder Bluff.", completion = "I am honored that you have chosen to join our delegation. I know you will make us proud, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13710] = { id = 13710, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valiant Of Undercity", description = "Welcome, champion. The Forsaken delegation could always use more {class}s like you. Would you join us?\n\nYou will train and rise through the ranks as you have before, but when you are named a champion of the Undecity, your gruntling will have the option of carrying our banner into battle.", sourceObjective = "Speak with Deathstalker Visceri again if you wish to become a valiant of the Undercity.", completion = "You have chosen wisely, {name}. Both of us will benefit from this arrangement.", sourceObjectiveStatus = "unverified-source-field" }
quests[13711] = { id = 13711, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valiant Of Silvermoon", description = "So, you have become a champion? Then, you have proven yourself a worthy combatant and I would proudly welcome you into Silvermoon's delegation.\n\nYou will train and rise through the ranks as you have before, but when you are named a champion of Silvermoon, your gruntling will have the option of carrying our banner into battle.", sourceObjective = "Speak with Eressea Dawnsinger again if you wish to become a valiant of Silvermoon.", completion = "It will be an honor training and competing with you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13713] = { id = 13713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Valiant's Challenge", description = "You are nearly ready to compete on behalf of Ironforge in the grand melee. To prove yourself worthy to enter the lists on behalf of our city, you must defeat a champion of the Argent Crusade.\n\nGo to the stables outside the pavilion, equip your lance, and mount up. Speak to Squire Danny at the Argent Valiants' Ring on the western edge of the grounds. The squire will call out your opponent when you're ready.\n\nAfter the battle is concluded, we will speak of the outcome.", sourceObjective = "Speak with Squire Danny to summon your opponent. Once you have defeated the Argent Champion, return to Lana Stouthammer at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion.", completion = "You have proven yourself worthy of the title of champion, {name}. You will compete at the tournament's highest level on behalf of Ironforge, riding in the grand melee with your weapon at the ready and our mighty pennant at your back.", sourceObjectiveStatus = "unverified-source-field" }
